  1→// SPDX-License-Identifier: MIT OR Apache-2.0
  2→//! Error types for the Neumann gRPC server.
  3→
  4→use thiserror::Error;
  5→use tonic::Status;
  6→
  7→/// Server error type.
  8→#[derive(Error, Debug)]
  9→#[non_exhaustive]
 10→pub enum ServerError {
 11→    /// Configuration error.
 12→    #[error("configuration error: {0}")]
 13→    Config(String),
 14→
 15→    /// Transport error.
 16→    #[error("transport error: {0}")]
 17→    Transport(#[from] tonic::transport::Error),
 18→
 19→    /// Query execution error.
 20→    #[error("query error: {0}")]
 21→    Query(String),
 22→
 23→    /// Authentication error.
 24→    #[error("authentication error: {0}")]
 25→    Auth(String),
 26→
 27→    /// Blob storage error.
 28→    #[error("blob error: {0}")]
 29→    Blob(String),
 30→
 31→    /// Internal server error.
 32→    #[error("internal error: {0}")]
 33→    Internal(String),
 34→
 35→    /// Invalid argument.
 36→    #[error("invalid argument: {0}")]
 37→    InvalidArgument(String),
 38→
 39→    /// Resource not found.
 40→    #[error("not found: {0}")]
 41→    NotFound(String),
 42→
 43→    /// Permission denied.
 44→    #[error("permission denied: {0}")]
 45→    PermissionDenied(String),
 46→
 47→    /// I/O error.
 48→    #[error("I/O error: {0}")]
 49→    Io(#[from] std::io::Error),
 50→
 51→    /// Rate limit exceeded.
 52→    #[error("rate limit exceeded: {0}")]
 53→    RateLimited(String),
 54→}
 55→
 56→/// Generic internal error message for client responses.
 57→const INTERNAL_ERROR_MESSAGE: &str = "An internal error occurred. Please try again later.";
 58→
 59→impl From<ServerError> for Status {
 60→    fn from(err: ServerError) -> Self {
 61→        match &err {
 62→            ServerError::Config(msg)
 63→            | ServerError::Query(msg)
 64→            | ServerError::InvalidArgument(msg) => Self::invalid_argument(msg.clone()),
 65→            ServerError::Transport(e) => {
 66→                tracing::warn!(error = %e, "Transport error");
 67→                Self::unavailable("Service temporarily unavailable")
 68→            },
 69→            ServerError::Auth(msg) => Self::unauthenticated(msg.clone()),
 70→            ServerError::Blob(msg) => {
 71→                tracing::error!(error = %msg, "Blob storage error");
 72→                Self::internal(INTERNAL_ERROR_MESSAGE)
 73→            },
 74→            ServerError::Internal(msg) => {
 75→                tracing::error!(error = %msg, "Internal server error");
 76→                Self::internal(INTERNAL_ERROR_MESSAGE)
 77→            },
 78→            ServerError::NotFound(msg) => Self::not_found(msg.clone()),
 79→            ServerError::PermissionDenied(msg) => Self::permission_denied(msg.clone()),
 80→            ServerError::Io(e) => {
 81→                tracing::error!(error = %e, "I/O error");
 82→                Self::internal(INTERNAL_ERROR_MESSAGE)
 83→            },
 84→            ServerError::RateLimited(msg) => Self::resource_exhausted(msg.clone()),
 85→        }
 86→    }
 87→}
 88→
 89→impl From<query_router::RouterError> for ServerError {
 90→    fn from(err: query_router::RouterError) -> Self {
 91→        Self::Query(err.to_string())
 92→    }
 93→}
 94→
 95→impl From<tensor_blob::BlobError> for ServerError {
 96→    fn from(err: tensor_blob::BlobError) -> Self {
 97→        Self::Blob(err.to_string())
 98→    }
 99→}
100→
101→/// Result type alias for server operations.
102→pub type Result<T> = std::result::Result<T, ServerError>;
103→
104→/// Sanitize an error message for client responses.
105→///
106→/// This function logs the full error details server-side and returns a
107→/// sanitized message that is safe to expose to clients. Internal errors
108→/// are replaced with a generic message to avoid leaking implementation details.
109→pub fn sanitize_internal_error<E: std::fmt::Display>(error: E) -> Status {
110→    tracing::error!(error = %error, "Internal server error");
111→    Status::internal(INTERNAL_ERROR_MESSAGE)
112→}
113→
114→/// Sanitize any error that should not expose details to clients.
115→///
116→/// This logs the full error and returns an appropriate generic response.
117→pub fn sanitize_error<E: std::fmt::Display>(error: E, code: tonic::Code) -> Status {
118→    let msg = match code {
119→        tonic::Code::Internal => {
120→            tracing::error!(error = %error, "Internal server error");
121→            INTERNAL_ERROR_MESSAGE.to_string()
122→        },
123→        tonic::Code::Unavailable => {
124→            tracing::warn!(error = %error, "Service unavailable");
125→            "Service temporarily unavailable".to_string()
126→        },
127→        _ => error.to_string(),
128→    };
129→    Status::new(code, msg)
130→}
131→
132→#[cfg(test)]
133→mod tests {
134→    use super::*;
135→
136→    #[test]
137→    fn test_config_error_to_status() {
138→        let err = ServerError::Config("invalid port".to_string());
139→        let status: Status = err.into();
140→        assert_eq!(status.code(), tonic::Code::InvalidArgument);
141→    }
142→
143→    #[test]
144→    fn test_query_error_to_status() {
145→        let err = ServerError::Query("syntax error".to_string());
146→        let status: Status = err.into();
147→        assert_eq!(status.code(), tonic::Code::InvalidArgument);
148→    }
149→
150→    #[test]
151→    fn test_auth_error_to_status() {
152→        let err = ServerError::Auth("invalid token".to_string());
153→        let status: Status = err.into();
154→        assert_eq!(status.code(), tonic::Code::Unauthenticated);
155→    }
156→
157→    #[test]
158→    fn test_not_found_error_to_status() {
159→        let err = ServerError::NotFound("artifact not found".to_string());
160→        let status: Status = err.into();
161→        assert_eq!(status.code(), tonic::Code::NotFound);
162→    }
163→
164→    #[test]
165→    fn test_permission_denied_to_status() {
166→        let err = ServerError::PermissionDenied("access denied".to_string());
167→        let status: Status = err.into();
168→        assert_eq!(status.code(), tonic::Code::PermissionDenied);
169→    }
170→
171→    #[test]
172→    fn test_internal_error_to_status() {
173→        let err = ServerError::Internal("unexpected error".to_string());
174→        let status: Status = err.into();
175→        assert_eq!(status.code(), tonic::Code::Internal);
176→    }
177→
178→    #[test]
179→    fn test_blob_error_to_status() {
180→        let err = ServerError::Blob("storage error".to_string());
181→        let status: Status = err.into();
182→        assert_eq!(status.code(), tonic::Code::Internal);
183→    }
184→
185→    #[test]
186→    fn test_invalid_argument_to_status() {
187→        let err = ServerError::InvalidArgument("bad input".to_string());
188→        let status: Status = err.into();
189→        assert_eq!(status.code(), tonic::Code::InvalidArgument);
190→    }
191→
192→    #[test]
193→    fn test_error_display() {
194→        let err = ServerError::Config("test config error".to_string());
195→        assert_eq!(err.to_string(), "configuration error: test config error");
196→
197→        let err = ServerError::Query("test query error".to_string());
198→        assert_eq!(err.to_string(), "query error: test query error");
199→    }
200→
201→    #[test]
202→    fn test_rate_limited_to_status() {
203→        let err = ServerError::RateLimited("too many requests".to_string());
204→        let status: Status = err.into();
205→        assert_eq!(status.code(), tonic::Code::ResourceExhausted);
206→    }
207→
208→    #[test]
209→    fn test_rate_limited_error_display() {
210→        let err = ServerError::RateLimited("too many requests".to_string());
211→        assert_eq!(err.to_string(), "rate limit exceeded: too many requests");
212→    }
213→
214→    #[test]
215→    fn test_internal_error_sanitization() {
216→        // Internal errors should not expose their message to clients
217→        let err = ServerError::Internal("secret database connection string".to_string());
218→        let status: Status = err.into();
219→        assert_eq!(status.code(), tonic::Code::Internal);
220→        assert!(!status.message().contains("secret"));
221→        assert!(status.message().contains("internal error"));
222→    }
