227→        let err = ServerError::Blob("failed to write to /var/data/secrets".to_string());
228→        let status: Status = err.into();
229→        assert_eq!(status.code(), tonic::Code::Internal);
230→        assert!(!status.message().contains("/var/data"));
231→    }
