  1→// SPDX-License-Identifier: MIT OR Apache-2.0
  2→//! Error types for `tensor_chain`.
  3→
  4→use thiserror::Error;
  5→
  6→use crate::atomic_io::AtomicIoError;
  7→use crate::embedding::EmbeddingError;
  8→use crate::raft_wal::WalError;
  9→use crate::snapshot_buffer::SnapshotBufferError;
 10→use crate::snapshot_streaming::StreamingError;
 11→
 12→/// Result type for `tensor_chain` operations.
 13→pub type Result<T> = std::result::Result<T, ChainError>;
 14→
 15→/// Errors that can occur in `tensor_chain` operations.
 16→#[derive(Debug, Error)]
 17→#[non_exhaustive]
 18→pub enum ChainError {
 19→    /// WAL error.
 20→    #[error("WAL error: {0}")]
 21→    Wal(#[from] WalError),
 22→
 23→    /// Atomic I/O error.
 24→    #[error("atomic I/O error: {0}")]
 25→    AtomicIo(#[from] AtomicIoError),
 26→
 27→    /// Snapshot buffer error.
 28→    #[error("snapshot buffer error: {0}")]
 29→    SnapshotBuffer(#[from] SnapshotBufferError),
 30→
 31→    /// Snapshot streaming error.
 32→    #[error("streaming error: {0}")]
 33→    Streaming(#[from] StreamingError),
 34→
 35→    /// Embedding operation error.
 36→    #[error("embedding error: {0}")]
 37→    EmbeddingOp(#[from] EmbeddingError),
 38→
 39→    /// Block validation failed.
 40→    #[error("block validation failed: {0}")]
 41→    ValidationFailed(String),
 42→
 43→    /// Invalid block hash.
 44→    #[error("invalid block hash: expected {expected}, got {actual}")]
 45→    InvalidHash { expected: String, actual: String },
 46→
 47→    /// Block not found.
 48→    #[error("block not found at height {0}")]
 49→    BlockNotFound(u64),
 50→
 51→    /// Transaction failed.
 52→    #[error("transaction failed: {0}")]
 53→    TransactionFailed(String),
 54→
 55→    /// Workspace isolation error.
 56→    #[error("workspace error: {0}")]
 57→    WorkspaceError(String),
 58→
 59→    /// Checkpoint error.
 60→    #[error("checkpoint error: {0}")]
 61→    CheckpointError(String),
 62→
 63→    /// Codebook validation error.
 64→    #[error("codebook validation failed: {0}")]
 65→    CodebookError(String),
 66→
 67→    /// State transition not valid.
 68→    #[error("invalid state transition: {0}")]
 69→    InvalidTransition(String),
 70→
 71→    /// Conflict detected during merge.
 72→    #[error("semantic conflict detected: similarity {similarity:.3}")]
 73→    ConflictDetected { similarity: f32 },
 74→
 75→    /// Merge failed.
 76→    #[error("merge failed: {0}")]
 77→    MergeFailed(String),
 78→
 79→    /// Consensus error.
 80→    #[error("consensus error: {0}")]
 81→    ConsensusError(String),
 82→
 83→    /// Network error.
 84→    #[error("network error: {0}")]
 85→    NetworkError(String),
 86→
 87→    /// Serialization error.
 88→    #[error("serialization error: {0}")]
 89→    SerializationError(String),
 90→
 91→    /// Storage error.
 92→    #[error("storage error: {0}")]
 93→    StorageError(String),
 94→
 95→    /// Graph engine error.
 96→    #[error("graph error: {0}")]
 97→    GraphError(String),
 98→
 99→    /// Crypto error.
100→    #[error("crypto error: {0}")]
101→    CryptoError(String),
102→
103→    /// Gossip signature verification failed.
104→    #[error("gossip signature invalid: {reason}")]
105→    GossipSignatureInvalid {
106→        /// Reason for signature invalidity.
107→        reason: String,
108→    },
109→
110→    /// Gossip message replay detected.
111→    #[error("gossip replay detected: sender {sender}, sequence {sequence}")]
112→    GossipReplayDetected {
113→        /// Sender `NodeId`.
114→        sender: String,
115→        /// Replayed sequence number.
116→        sequence: u64,
117→    },
118→
119→    /// Unknown gossip sender not in validator registry.
120→    #[error("unknown gossip sender: {0}")]
121→    UnknownGossipSender(String),
122→
123→    /// Chain is empty.
124→    #[error("chain is empty")]
125→    EmptyChain,
126→
127→    /// Invalid chain state.
128→    #[error("invalid chain state: {0}")]
129→    InvalidState(String),
130→
131→    /// Replication queue is full (backpressure).
132→    #[error("replication queue full: {pending_count} pending updates")]
133→    QueueFull { pending_count: usize },
134→
135→    /// Snapshot error.
136→    #[error("snapshot error: {0}")]
137→    SnapshotError(String),
138→
139→    /// Not the leader node (membership changes require leader).
140→    #[error("not the leader")]
141→    NotLeader,
142→
143→    /// Membership change already in progress.
144→    #[error("membership change in progress at index {0}")]
145→    MembershipChangeInProgress(u64),
146→
147→    /// Node not found in membership.
148→    #[error("node not found: {0}")]
149→    NodeNotFound(String),
150→
151→    /// Deadlock detected in distributed transaction.
152→    #[error("deadlock detected: cycle {cycle:?}, victim tx {victim}")]
153→    DeadlockDetected {
154→        /// Transaction IDs in the deadlock cycle.
155→        cycle: Vec<u64>,
156→        /// Selected victim transaction ID.
157→        victim: u64,
158→    },
159→
160→    /// Handler operation timed out.
161→    #[error("handler timeout: {operation} exceeded {timeout_ms}ms")]
162→    HandlerTimeout {
163→        /// The operation that timed out.
164→        operation: String,
165→        /// The timeout in milliseconds.
166→        timeout_ms: u64,
167→    },
168→
169→    /// Message validation failed.
170→    #[error("message validation failed: {message_type}: {reason}")]
171→    MessageValidationFailed {
172→        /// Type of message that failed validation.
173→        message_type: &'static str,
174→        /// Reason for validation failure.
175→        reason: String,
176→    },
177→
178→    /// Invalid embedding in message.
179→    #[error("invalid embedding (dimension {dimension}): {reason}")]
180→    InvalidEmbedding {
181→        /// Dimension of the invalid embedding.
182→        dimension: usize,
183→        /// Reason for invalidity.
184→        reason: String,
185→    },
186→
187→    /// Numeric field out of bounds.
188→    #[error("numeric out of bounds: {field} = {value} (expected {expected})")]
189→    NumericOutOfBounds {
190→        /// Field name.
191→        field: String,
192→        /// Actual value.
193→        value: String,
194→        /// Expected bounds.
195→        expected: String,
196→    },
197→
198→    /// Delta update integrity check failed.
199→    #[error("update integrity failed for key '{key}' at index {index}")]
200→    UpdateIntegrityFailed {
201→        /// Key of the update.
202→        key: String,
203→        /// Index in the batch.
204→        index: usize,
205→    },
206→
207→    /// Delta batch integrity check failed.
208→    #[error("batch integrity failed: sequence {sequence} from {source_node}")]
209→    BatchIntegrityFailed {
210→        /// Batch sequence number.
211→        sequence: u64,
212→        /// Source node.
213→        source_node: String,
214→    },
215→
216→    /// Clock error (system time unavailable or invalid).
217→    #[error("clock error: {0}")]
218→    ClockError(String),
219→}
