  2→use std::fmt;
  3→
  4→#[derive(Debug, Clone, PartialEq, Eq)]
  5→pub enum BlobError {
  6→    /// Artifact not found.
  7→    NotFound(String),
  8→    /// Chunk missing from storage.
  9→    ChunkMissing(String),
 10→    /// Checksum verification failed.
 11→    ChecksumMismatch { expected: String, actual: String },
 12→    /// Storage error from `TensorStore`.
 13→    StorageError(String),
 14→    /// Graph engine error.
 15→    GraphError(String),
 16→    /// Vector engine error.
 17→    VectorError(String),
 18→    /// Invalid artifact ID format.
 19→    InvalidArtifactId(String),
 20→    /// Invalid configuration.
 21→    InvalidConfig(String),
 22→    /// IO error during streaming.
 23→    IoError(String),
 24→    /// GC error.
 25→    GcError(String),
 26→    /// Artifact already exists.
 27→    AlreadyExists(String),
 28→    /// Empty data provided.
 29→    EmptyData,
 30→    /// Dimension mismatch for embeddings.
 31→    DimensionMismatch { expected: usize, got: usize },
 32→}
 33→
 34→impl fmt::Display for BlobError {
 35→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 36→        match self {
 37→            Self::NotFound(id) => write!(f, "artifact not found: {id}"),
 38→            Self::ChunkMissing(hash) => write!(f, "chunk missing: {hash}"),
 39→            Self::ChecksumMismatch { expected, actual } => {
 40→                write!(f, "checksum mismatch: expected {expected}, got {actual}")
 41→            },
 42→            Self::StorageError(msg) => write!(f, "storage error: {msg}"),
 43→            Self::GraphError(msg) => write!(f, "graph error: {msg}"),
 44→            Self::VectorError(msg) => write!(f, "vector error: {msg}"),
 45→            Self::InvalidArtifactId(id) => write!(f, "invalid artifact id: {id}"),
 46→            Self::InvalidConfig(msg) => write!(f, "invalid config: {msg}"),
 47→            Self::IoError(msg) => write!(f, "io error: {msg}"),
 48→            Self::GcError(msg) => write!(f, "gc error: {msg}"),
 49→            Self::AlreadyExists(id) => write!(f, "artifact already exists: {id}"),
 50→            Self::EmptyData => write!(f, "empty data provided"),
 51→            Self::DimensionMismatch { expected, got } => {
 52→                write!(f, "dimension mismatch: expected {expected}, got {got}")
 53→            },
 54→        }
 55→    }
 56→}
 57→
 58→impl std::error::Error for BlobError {}
 59→
 60→impl From<tensor_store::TensorStoreError> for BlobError {
 61→    fn from(e: tensor_store::TensorStoreError) -> Self {
 62→        Self::StorageError(e.to_string())
 63→    }
 64→}
 65→
