 67→impl From<graph_engine::GraphError> for BlobError {
 68→    fn from(e: graph_engine::GraphError) -> Self {
 69→        Self::GraphError(e.to_string())
 70→    }
 71→}
 72→
 73→#[cfg(feature = "vector")]
 74→impl From<vector_engine::VectorError> for BlobError {
 75→    fn from(e: vector_engine::VectorError) -> Self {
 76→        Self::VectorError(e.to_string())
 77→    }
 78→}
 79→
 80→impl From<std::io::Error> for BlobError {
 81→    fn from(e: std::io::Error) -> Self {
 82→        Self::IoError(e.to_string())
 83→    }
 84→}
