 1→// SPDX-License-Identifier: MIT OR Apache-2.0
 2→//! Neumann CLI entry point.
 3→
 4→use clap::Parser;
 5→use neumann_shell::{cli::Cli, Shell, ShellConfig};
 6→use std::fs;
 7→
 8→fn main() {
 9→    let cli = Cli::parse();
10→
11→    // NO_COLOR convention: any non-empty value disables color.
12→    let no_color = cli.no_color || std::env::var("NO_COLOR").is_ok_and(|v| !v.is_empty());
13→
14→    let config = ShellConfig {
15→        no_color,
16→        no_boot: cli.no_boot,
17→        quiet: cli.quiet,
18→        ..Default::default()
19→    };
20→
21→    let mut shell = Shell::with_config(config);
22→
23→    // Execute file mode
24→    if let Some(file) = cli.file {
25→        let content = match fs::read_to_string(&file) {
26→            Ok(c) => c,
27→            Err(e) => {
28→                eprintln!("Error reading {}: {e}", file.display());
29→                std::process::exit(1);
30→            },
31→        };
32→
33→        for line in content.lines() {
34→            let line = line.trim();
35→            if line.is_empty() || line.starts_with("--") || line.starts_with('#') {
36→                continue;
37→            }
38→            match shell.execute_line(line) {
39→                Ok(output) => {
40→                    if !output.is_empty() && !cli.quiet {
41→                        println!("{output}");
42→                    }
43→                },
44→                Err(e) => {
45→                    eprintln!("{e}");
46→                    std::process::exit(1);
47→                },
48→            }
49→        }
50→        return;
51→    }
52→
53→    // Execute command mode
54→    if let Some(cmd) = cli.command {
55→        match shell.execute_line(&cmd) {
56→            Ok(output) => {
57→                if !output.is_empty() {
58→                    println!("{output}");
59→                }
60→            },
61→            Err(e) => {
62→                eprintln!("{e}");
63→                std::process::exit(1);
64→            },
65→        }
66→        return;
67→    }
68→
69→    // Interactive mode
70→    if let Err(e) = shell.run() {
71→        eprintln!("{e}");
72→        std::process::exit(1);
73→    }
74→}
