 43→/// Milliseconds since UNIX epoch, serializable replacement for Instant.
 44→pub type EpochMillis = u64;
 45→
 46→/// Get current time as epoch milliseconds.
 47→fn now_epoch_millis() -> EpochMillis {
 48→    #[allow(clippy::cast_possible_truncation)]
 49→    let ms = SystemTime::now()
 50→        .duration_since(UNIX_EPOCH)
 51→        .unwrap_or_default()
 52→        .as_millis() as u64;
 53→    ms
 54→}
