 56→/// Shard identifier.
 57→pub type ShardId = usize;
 58→
 59→/// Phase of a distributed transaction.
 60→#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
 61→#[non_exhaustive]
 62→pub enum TxPhase {
 63→    /// Transaction is being prepared (Phase 1).
 64→    #[default]
 65→    Preparing,
 66→    /// All participants voted YES.
 67→    Prepared,
 68→    /// Transaction is being committed (Phase 2).
 69→    Committing,
 70→    /// Transaction has been committed.
 71→    Committed,
 72→    /// Transaction is being aborted.
 73→    Aborting,
 74→    /// Transaction has been aborted.
 75→    Aborted,
 76→}
