 78→/// Undo entry capturing the previous state of a key for rollback.
 79→#[derive(Debug, Clone, Serialize, Deserialize)]
 80→pub enum UndoEntry {
 81→    /// Key existed before - restore this value on rollback.
 82→    Restore {
 83→        key: String,
 84→        /// Bincode-serialized `TensorData`.
 85→        data: Vec<u8>,
 86→    },
 87→    /// Key did not exist before - delete on rollback.
 88→    Delete { key: String },
 89→}
 90→
 91→impl UndoEntry {
 92→    /// Capture the current state of a key from the store.
 93→    #[must_use]
 94→    pub fn capture(key: &str, store: &TensorStore) -> Self {
 95→        store.get(key).map_or_else(
 96→            |_| Self::Delete {
 97→                key: key.to_string(),
 98→            },
 99→            |data| {
100→                let bytes = bitcode::serialize(&data).unwrap_or_default();
101→                Self::Restore {
102→                    key: key.to_string(),
103→                    data: bytes,
104→                }
105→            },
106→        )
107→    }
108→
109→    /// Apply this undo entry to restore the previous state.
110→    ///
111→    /// # Errors
112→    ///
113→    /// Returns an error if deserialization or store write fails.
114→    pub fn apply(&self, store: &TensorStore) -> Result<()> {
115→        match self {
116→            Self::Restore { key, data } => {
117→                let tensor: TensorData = bitcode::deserialize(data)
118→                    .map_err(|e| ChainError::SerializationError(e.to_string()))?;
119→                store
120→                    .put(key, tensor)
121→                    .map_err(|e| ChainError::StorageError(e.to_string()))?;
122→            },
123→            Self::Delete { key } => {
124→                // Idempotent delete - ignore NotFound
125→                store.delete(key).ok();
126→            },
127→        }
128→        Ok(())
129→    }
130→
131→    /// Get the key affected by this undo entry.
132→    #[must_use]
133→    pub fn key(&self) -> &str {
134→        match self {
135→            Self::Restore { key, .. } | Self::Delete { key } => key,
136→        }
137→    }
138→
139→    /// Compute a CRC32 checksum of this undo entry for integrity verification.
140→    #[must_use]
141→    pub fn checksum(&self) -> u32 {
142→        let mut hasher = crc32fast::Hasher::new();
143→        match self {
144→            Self::Restore { key, data } => {
145→                hasher.update(b"R"); // tag byte
146→                hasher.update(key.as_bytes());
147→                hasher.update(data);
148→            },
149→            Self::Delete { key } => {
150→                hasher.update(b"D"); // tag byte

