139→            consecutive_failures: AtomicU32::new(0),
140→            rate_limiter,
141→            audit_logger,
142→            metrics,
143→        }
144→    }
145→
146→    /// Record a successful query execution.
147→    fn record_success(&self) {
148→        self.consecutive_failures.store(0, Ordering::SeqCst);
149→        if let Some(ref health) = self.health_state {
150→            health.set_query_service_healthy(true);
151→        }
152→    }
153→
154→    /// Record a failed query execution.
155→    fn record_failure(&self) {
156→        let failures = self.consecutive_failures.fetch_add(1, Ordering::SeqCst) + 1;
157→        if failures >= FAILURE_THRESHOLD {
158→            if let Some(ref health) = self.health_state {
159→                health.set_query_service_healthy(false);
160→                tracing::warn!(
161→                    "Query service marked unhealthy after {} consecutive failures",
162→                    failures
163→                );
164→            }
165→        }
166→    }
167→
168→    /// Execute a query and return the result.
169→    ///
170→    /// Uses a read lock for queries without identity (the common case),
171→    /// and a write lock only when identity must be set for vault access.
172→    fn execute_query(&self, query: &str, identity: Option<&str>) -> Result<QueryResult, Status> {
173→        if let Some(id) = identity {
174→            let mut router = self.router.write();
175→            router.set_identity(id);
176→            match router.execute(query) {
177→                Ok(result) => {
178→                    self.record_success();
179→                    return Ok(result);
180→                },
181→                Err(e) => {
182→                    self.record_failure();
183→                    tracing::error!("Query execution error: {}", e);
184→                    return Err(crate::error::sanitize_internal_error(e));
185→                },
186→            }
187→        }
188→
189→        let router = self.router.read();
190→        match router.execute(query) {
191→            Ok(result) => {
192→                self.record_success();
193→                Ok(result)
194→            },
195→            Err(e) => {
196→                self.record_failure();
197→                tracing::error!("Query execution error: {}", e);
198→                Err(crate::error::sanitize_internal_error(e))
199→            },
200→        }

