269→    type DownloadStream =
270→        Pin<Box<dyn tokio_stream::Stream<Item = Result<BlobDownloadChunk, Status>> + Send>>;
271→
272→    async fn download(
273→        &self,
274→        request: Request<BlobDownloadRequest>,
275→    ) -> Result<Response<Self::DownloadStream>, Status> {
276→        let start = Instant::now();
277→
278→        // Validate authentication with rate limiting and audit
279→        let identity = match auth::validate_request_with_audit(
280→            &request,
281→            &self.auth_config,
282→            self.rate_limiter.as_deref(),
283→            self.audit_logger.as_deref(),
284→        ) {
285→            Ok(id) => id,
286→            Err(status) => {
287→                if let Some(ref m) = self.metrics {
288→                    if status.code() == tonic::Code::Unauthenticated {
289→                        m.record_auth_failure("invalid_key");
290→                    }
291→                    let latency_ms = start.elapsed().as_secs_f64() * 1000.0;
292→                    m.record_request("blob", "download", false, latency_ms);
293→                }
294→                return Err(status);
295→            },
296→        };
297→
298→        // Check blob-specific rate limit
299→        if let Some(ref limiter) = self.rate_limiter {
300→            if let Some(ref id) = identity {
301→                if let Err(msg) = limiter.check_and_record(id, Operation::BlobOp) {
302→                    if let Some(ref logger) = self.audit_logger {
303→                        logger.record(
304→                            AuditEvent::RateLimited {
305→                                identity: id.clone(),
306→                                operation: "blob_op".to_string(),
307→                            },
308→                            None,
309→                        );
310→                    }
311→                    if let Some(ref m) = self.metrics {
312→                        m.record_rate_limited(id, "blob_download");
313→                        let latency_ms = start.elapsed().as_secs_f64() * 1000.0;
314→                        m.record_request("blob", "download", false, latency_ms);
315→                    }
316→                    return Err(Status::resource_exhausted(msg));
317→                }
318→            }
319→        }
320→
321→        let artifact_id = request.into_inner().artifact_id;
322→        let chunk_size = self.chunk_size;
323→
324→        // Get the blob data
325→        let store = self.blob_store.lock().await;
326→        let data = match store.get(&artifact_id).await {
327→            Ok(d) => d,
328→            Err(e) => {
329→                if let Some(ref m) = self.metrics {
330→                    let latency_ms = start.elapsed().as_secs_f64() * 1000.0;
331→                    m.record_request("blob", "download", false, latency_ms);
332→                }
333→                if matches!(e, tensor_blob::BlobError::NotFound(_)) {
334→                    return Err(Status::not_found(format!(
335→                        "artifact not found: {artifact_id}"
336→                    )));
337→                }
338→                tracing::error!("Blob download error: {e}");
339→                return Err(Status::internal("internal storage error"));
340→            },
341→        };
342→
343→        drop(store); // Release lock before streaming
344→
345→        // Audit the download
346→        if let Some(ref logger) = self.audit_logger {
347→            logger.record(
348→                AuditEvent::BlobDownload {
349→                    identity: identity.clone(),
350→                    artifact_id: artifact_id.clone(),
351→                },
352→                None,
353→            );
354→        }
355→
356→        // Record success metrics for download setup
357→        if let Some(ref m) = self.metrics {
358→            let latency_ms = start.elapsed().as_secs_f64() * 1000.0;
359→            m.record_request("blob", "download", true, latency_ms);
360→        }
361→
362→        let (tx, rx) = mpsc::channel(self.stream_channel_capacity);
363→
364→        // Spawn task to stream data
365→        tokio::spawn(async move {
366→            let chunks: Vec<_> = data.chunks(chunk_size).collect();
367→            let total_chunks = chunks.len();
368→
369→            for (i, chunk_data) in chunks.into_iter().enumerate() {
370→                let is_final = i == total_chunks - 1;
371→                let chunk = BlobDownloadChunk {
372→                    data: chunk_data.to_vec(),
373→                    is_final,
374→                };
375→
376→                if tx.send(Ok(chunk)).await.is_err() {
377→                    // Receiver dropped, stop sending
378→                    return;
379→                }
380→            }
381→        });
382→
383→        let stream = ReceiverStream::new(rx);
384→        Ok(Response::new(Box::pin(stream)))
385→    }
