616→
617→    /// Check if we have a joint quorum (majority in BOTH old and new configs).
618→    #[must_use]
619→    pub fn has_joint_quorum(&self, votes: &HashSet<NodeId>) -> bool {
620→        let old_quorum = crate::quorum_size(self.old_voters.len());
621→        let new_quorum = crate::quorum_size(self.new_voters.len());
622→
623→        let old_votes = self
624→            .old_voters
625→            .iter()
626→            .filter(|n| votes.contains(*n))
627→            .count();
628→        let new_votes = self
629→            .new_voters
630→            .iter()
631→            .filter(|n| votes.contains(*n))
632→            .count();
633→
634→        old_votes >= old_quorum && new_votes >= new_quorum
635→    }
636→
637→    #[must_use]
638→    pub fn all_voters(&self) -> Vec<NodeId> {
639→        let mut all: Vec<_> = self.old_voters.clone();
640→        for node in &self.new_voters {
641→            if !all.contains(node) {
642→                all.push(node.clone());
643→            }
644→        }
645→        all
646→    }
647→}
