649→/// Raft membership configuration.
650→///
651→/// Tracks voters, learners, and joint consensus state for dynamic membership.
652→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Default)]
653→pub struct RaftMembershipConfig {
654→    /// Current voting members.
655→    pub voters: Vec<NodeId>,
656→    /// Non-voting learners (catching up before becoming voters).
657→    pub learners: Vec<NodeId>,
658→    /// Joint configuration during membership transitions.
659→    pub joint: Option<JointConfig>,
660→    /// Log index where this configuration was committed.
661→    pub config_index: u64,
662→}
663→
664→impl RaftMembershipConfig {
665→    #[must_use]
666→    pub const fn new(voters: Vec<NodeId>) -> Self {
667→        Self {
668→            voters,
669→            learners: Vec::new(),
670→            joint: None,
671→            config_index: 0,
672→        }
673→    }
674→
675→    /// Check if we have quorum (considering joint consensus if active).
676→    #[must_use]
677→    pub fn has_quorum(&self, votes: &HashSet<NodeId>) -> bool {
678→        self.joint.as_ref().map_or_else(
679→            || {
680→                let quorum = crate::quorum_size(self.voters.len());
681→                self.voters.iter().filter(|n| votes.contains(*n)).count() >= quorum
682→            },
683→            |joint| joint.has_joint_quorum(votes),
684→        )
685→    }
686→
687→    /// Get all nodes that should receive log entries (voters + learners + joint).
688→    #[must_use]
689→    pub fn replication_targets(&self) -> Vec<NodeId> {
690→        let mut targets = self.voters.clone();
691→        targets.extend(self.learners.clone());
692→
693→        // Include new voters during joint consensus
694→        if let Some(ref joint) = self.joint {
695→            for node in &joint.new_voters {
696→                if !targets.contains(node) {
697→                    targets.push(node.clone());
698→                }
699→            }
700→        }
701→
702→        targets
703→    }
704→
705→    #[must_use]
706→    pub const fn in_joint_consensus(&self) -> bool {
707→        self.joint.is_some()
708→    }
709→
710→    pub fn add_learner(&mut self, node_id: NodeId) {
711→        if !self.learners.contains(&node_id) && !self.voters.contains(&node_id) {
712→            self.learners.push(node_id);
713→        }
714→    }
715→
716→    pub fn promote_learner(&mut self, node_id: &NodeId) -> bool {
717→        if let Some(pos) = self.learners.iter().position(|n| n == node_id) {
718→            self.learners.remove(pos);
719→            self.voters.push(node_id.clone());
720→            true
721→        } else {
722→            false
723→        }
724→    }
725→
726→    pub fn remove_node(&mut self, node_id: &NodeId) -> bool {
727→        if let Some(pos) = self.voters.iter().position(|n| n == node_id) {
728→            self.voters.remove(pos);
729→            return true;
730→        }
731→        if let Some(pos) = self.learners.iter().position(|n| n == node_id) {
732→            self.learners.remove(pos);
733→            return true;
734→        }
735→        false
736→    }
737→
738→    #[must_use]
739→    pub fn is_voter(&self, node_id: &NodeId) -> bool {
740→        self.voters.contains(node_id)
741→    }
742→
743→    #[must_use]
744→    pub fn is_learner(&self, node_id: &NodeId) -> bool {
745→        self.learners.contains(node_id)
746→    }
747→}
