 41→    /// Creates an "unexpected token" error.
 42→    pub fn unexpected(found: TokenKind, span: Span, expected: impl Into<String>) -> Self {
 43→        Self::new(
 44→            ParseErrorKind::UnexpectedToken {
 45→                found,
 46→                expected: expected.into(),
 47→            },
 48→            span,
 49→        )
 50→    }
 51→
 52→    /// Creates an "unexpected EOF" error.
 53→    pub fn unexpected_eof(span: Span, expected: impl Into<String>) -> Self {
 54→        Self::new(
 55→            ParseErrorKind::UnexpectedEof {
 56→                expected: expected.into(),
 57→            },
 58→            span,
 59→        )
 60→    }
 61→
 62→    /// Creates an "invalid syntax" error.
 63→    pub fn invalid(message: impl Into<String>, span: Span) -> Self {
 64→        Self::new(ParseErrorKind::InvalidSyntax(message.into()), span)
 65→    }
 66→
 67→    /// Adds a help message to the error.
 68→    #[must_use]
 69→    pub fn with_help(mut self, help: impl Into<String>) -> Self {
 70→        self.help = Some(help.into());
 71→        self
 72→    }
 73→
 74→    /// Formats the error with source context.
 75→    #[must_use]
 76→    #[allow(clippy::format_push_string)]
 77→    pub fn format_with_source(&self, source: &str) -> String {
 78→        let (line, col) = line_col(source, self.span.start);
 79→        let line_text = get_line(source, self.span.start);
 80→
 81→        let kind = &self.kind;
 82→        let mut result = format!("error: {kind}\n");
 83→        result.push_str(&format!("  --> line {line}:{col}\n"));
 84→        result.push_str("   |\n");
 85→        result.push_str(&format!("{line:3} | {line_text}\n"));
 86→        result.push_str("   | ");
 87→
 88→        // Add carets under the error
 89→        for _ in 0..(col - 1) {
 90→            result.push(' ');
 91→        }
 92→        let len = self.span.len().max(1) as usize;
 93→        let caret_len = len.min(line_text.len().saturating_sub(col - 1));
 94→        for _ in 0..caret_len.max(1) {
 95→            result.push('^');
 96→        }
 97→        result.push('\n');
 98→
 99→        if let Some(help) = &self.help {
100→            result.push_str(&format!("   = help: {help}\n"));
101→        }
102→
103→        result
104→    }
105→}
106→
107→impl fmt::Display for ParseError {
108→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
109→        write!(f, "{} at {}", self.kind, self.span)
110→    }
111→}
112→
113→impl std::error::Error for ParseError {}
114→
115→/// Parse error kinds.
116→#[derive(Clone, Debug)]
117→pub enum ParseErrorKind {
118→    /// Unexpected token
119→    UnexpectedToken {
120→        /// The token that was found.
121→        found: TokenKind,
122→        /// Description of what was expected.
123→        expected: String,
124→    },
125→    /// Unexpected end of input
126→    UnexpectedEof {
127→        /// Description of what was expected.
128→        expected: String,
129→    },
130→    /// Invalid syntax
131→    InvalidSyntax(String),
132→    /// Invalid number
133→    InvalidNumber(String),
134→    /// Unterminated string
135→    UnterminatedString,
136→    /// Unknown keyword or command
137→    UnknownCommand(String),
138→    /// Duplicate column
139→    DuplicateColumn(String),
140→    /// Invalid escape sequence
141→    InvalidEscape(char),
142→    /// Expression too deeply nested
143→    TooDeep,
144→    /// Custom error
145→    Custom(String),
146→}
147→
148→impl fmt::Display for ParseErrorKind {
149→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
150→        match self {
151→            Self::UnexpectedToken { found, expected } => {
152→                write!(f, "unexpected {found}, expected {expected}")
153→            },
154→            Self::UnexpectedEof { expected } => {
155→                write!(f, "unexpected end of input, expected {expected}")
156→            },
157→            Self::InvalidSyntax(msg) | Self::Custom(msg) => write!(f, "{msg}"),
158→            Self::InvalidNumber(msg) => write!(f, "invalid number: {msg}"),
159→            Self::UnterminatedString => write!(f, "unterminated string literal"),
160→            Self::UnknownCommand(cmd) => write!(f, "unknown command: {cmd}"),
161→            Self::DuplicateColumn(col) => write!(f, "duplicate column: {col}"),
162→            Self::InvalidEscape(c) => write!(f, "invalid escape sequence: \\{c}"),
163→            Self::TooDeep => write!(f, "expression nesting too deep"),
164→        }
165→    }
166→}
167→
168→/// A collection of parse errors.
169→#[derive(Clone, Debug, Default)]
170→pub struct Errors {
171→    errors: Vec<ParseError>,
172→}
173→
174→impl Errors {
175→    /// Creates an empty error collection.
176→    #[must_use]
177→    pub const fn new() -> Self {
178→        Self { errors: Vec::new() }
179→    }
180→
181→    /// Adds an error to the collection.
182→    pub fn push(&mut self, error: ParseError) {
183→        self.errors.push(error);
184→    }
185→
186→    /// Returns true if there are no errors.
187→    #[must_use]
188→    pub const fn is_empty(&self) -> bool {
189→        self.errors.is_empty()
190→    }
191→
192→    /// Returns the number of errors.
193→    #[must_use]
194→    pub const fn len(&self) -> usize {
195→        self.errors.len()
196→    }
197→
198→    /// Returns an iterator over the errors.
199→    pub fn iter(&self) -> impl Iterator<Item = &ParseError> {
200→        self.errors.iter()
201→    }
202→
203→    /// Consumes the collection and returns the errors.
204→    #[must_use]
205→    pub fn into_vec(self) -> Vec<ParseError> {
206→        self.errors
207→    }
208→
209→    /// Formats all errors with source context.
210→    #[must_use]
211→    pub fn format_with_source(&self, source: &str) -> String {
212→        self.errors
213→            .iter()
214→            .map(|e| e.format_with_source(source))
215→            .collect::<Vec<_>>()
216→            .join("\n")
217→    }
218→}
