  1→//! Observability infrastructure for relational engine.
  2→//!
  3→//! Provides structured logging, metrics, and query tracing for monitoring
  4→//! query performance and detecting missing indexes.
  5→
  6→use std::sync::atomic::{AtomicU64, Ordering};
  7→use std::time::Duration;
  8→
  9→use dashmap::DashMap;
 10→use tracing::warn;
 11→
 12→/// Query execution metrics for observability.
 13→#[derive(Debug, Clone)]
 14→pub struct QueryMetrics {
 15→    /// Table name.
 16→    pub table: String,
 17→    /// Operation type (select, insert, update, delete, join, etc.).
 18→    pub operation: &'static str,
 19→    /// Number of rows scanned.
 20→    pub rows_scanned: usize,
 21→    /// Number of rows returned.
 22→    pub rows_returned: usize,
 23→    /// Index used for the query, if any.
 24→    pub index_used: Option<String>,
 25→    /// Query execution duration.
 26→    pub duration: Duration,
 27→}
 28→
 29→impl QueryMetrics {
 30→    /// Creates new query metrics.
 31→    #[must_use]
 32→    pub fn new(table: impl Into<String>, operation: &'static str) -> Self {
 33→        Self {
 34→            table: table.into(),
 35→            operation,
 36→            rows_scanned: 0,
 37→            rows_returned: 0,
 38→            index_used: None,
 39→            duration: Duration::ZERO,
 40→        }
 41→    }
 42→
 43→    /// Sets the number of rows scanned.
 44→    #[must_use]
 45→    pub const fn with_rows_scanned(mut self, count: usize) -> Self {
 46→        self.rows_scanned = count;
 47→        self
 48→    }
 49→
 50→    /// Sets the number of rows returned.
 51→    #[must_use]
 52→    pub const fn with_rows_returned(mut self, count: usize) -> Self {
 53→        self.rows_returned = count;
 54→        self
 55→    }
 56→
 57→    /// Sets the index used.
 58→    #[must_use]
 59→    pub fn with_index(mut self, index: impl Into<String>) -> Self {
 60→        self.index_used = Some(index.into());
 61→        self
 62→    }
 63→
 64→    /// Sets the query duration.
 65→    #[must_use]
 66→    pub const fn with_duration(mut self, duration: Duration) -> Self {
 67→        self.duration = duration;
 68→        self
 69→    }
 70→}
 71→
 72→/// Report of index misses for a specific table/column combination.
 73→#[derive(Debug, Clone)]
 74→pub struct IndexMissReport {
 75→    /// Table name.
 76→    pub table: String,
 77→    /// Column name.
 78→    pub column: String,
 79→    /// Number of queries that missed this index.
 80→    pub miss_count: u64,
 81→    /// Number of queries that hit this index.
 82→    pub hit_count: u64,
 83→}
 84→
 85→/// Tracks index usage to detect missing indexes.
 86→#[derive(Debug, Default)]
 87→pub struct IndexTracker {
 88→    /// Tracks hits per (table, column).
 89→    hits: DashMap<(String, String), AtomicU64>,
 90→    /// Tracks misses per (table, column).
 91→    misses: DashMap<(String, String), AtomicU64>,
 92→}
