  9→/// Error types for client operations.
 10→#[derive(Debug, Error)]
 11→#[non_exhaustive]
 12→pub enum ClientError {
 13→    /// Connection error.
 14→    #[error("connection error: {0}")]
 15→    Connection(String),
 16→
 17→    /// Query execution error.
 18→    #[error("query error: {0}")]
 19→    Query(String),
 20→
 21→    /// Authentication error.
 22→    #[error("authentication failed: {0}")]
 23→    Authentication(String),
 24→
 25→    /// Permission denied.
 26→    #[error("permission denied: {0}")]
 27→    PermissionDenied(String),
 28→
 29→    /// Resource not found.
 30→    #[error("not found: {0}")]
 31→    NotFound(String),
 32→
 33→    /// Invalid argument.
 34→    #[error("invalid argument: {0}")]
 35→    InvalidArgument(String),
 36→
 37→    /// Parse error.
 38→    #[error("parse error: {0}")]
 39→    Parse(String),
 40→
 41→    /// Internal error.
 42→    #[error("internal error: {0}")]
 43→    Internal(String),
 44→
 45→    /// Timeout error.
 46→    #[error("timeout: {0}")]
 47→    Timeout(String),
 48→
 49→    /// Server unavailable.
 50→    #[error("server unavailable: {0}")]
 51→    Unavailable(String),
 52→}
 53→
 54→impl ClientError {
 55→    /// Get the error code.
 56→    #[must_use]
 57→    pub const fn code(&self) -> u32 {
 58→        match self {
 59→            Self::Query(_) => 9,    // QUERY_ERROR
 60→            Self::Parse(_) => 8,    // PARSE_ERROR
 61→            Self::Internal(_) => 7, // INTERNAL
 62→            Self::Connection(_) | Self::Timeout(_) | Self::Unavailable(_) => 6, // UNAVAILABLE
 63→            Self::Authentication(_) => 5, // UNAUTHENTICATED
 64→            Self::PermissionDenied(_) => 3, // PERMISSION_DENIED
 65→            Self::NotFound(_) => 2, // NOT_FOUND
 66→            Self::InvalidArgument(_) => 1, // INVALID_ARGUMENT
 67→        }
 68→    }
 69→
 70→    /// Check if this is a retryable error.
 71→    #[must_use]
 72→    pub const fn is_retryable(&self) -> bool {
 73→        matches!(
 74→            self,
 75→            Self::Connection(_) | Self::Timeout(_) | Self::Unavailable(_)
 76→        )
 77→    }
 78→}
