 81→impl From<tonic::Status> for ClientError {
 82→    fn from(status: tonic::Status) -> Self {
 83→        match status.code() {
 84→            tonic::Code::InvalidArgument => Self::InvalidArgument(status.message().to_string()),
 85→            tonic::Code::NotFound => Self::NotFound(status.message().to_string()),
 86→            tonic::Code::PermissionDenied => Self::PermissionDenied(status.message().to_string()),
 87→            tonic::Code::Unauthenticated => Self::Authentication(status.message().to_string()),
 88→            tonic::Code::Unavailable => Self::Unavailable(status.message().to_string()),
 89→            tonic::Code::DeadlineExceeded => Self::Timeout(status.message().to_string()),
 90→            _ => Self::Internal(status.message().to_string()),
 91→        }
 92→    }
 93→}
