  9→/// Errors specific to TCP transport operations.
 10→#[derive(Debug)]
 11→#[non_exhaustive]
 12→pub enum TcpError {
 13→    /// Connection to peer failed.
 14→    ConnectionFailed { peer: String, reason: String },
 15→
 16→    /// Connection was closed by peer.
 17→    ConnectionClosed,
 18→
 19→    /// Operation timed out.
 20→    Timeout {
 21→        operation: &'static str,
 22→        timeout_ms: u64,
 23→    },
 24→
 25→    /// Message exceeds maximum size.
 26→    MessageTooLarge { size: usize, max_size: usize },
 27→
 28→    /// Failed to serialize or deserialize message.
 29→    Serialization(String),
 30→
 31→    /// IO error.
 32→    Io(std::io::Error),
 33→
 34→    /// Peer not found in connection pool.
 35→    PeerNotFound(String),
 36→
 37→    /// Backpressure: outbound queue full.
 38→    BackpressureFull { peer: String, queue_size: usize },
 39→
 40→    /// TLS error.
 41→    TlsError(String),
 42→
 43→    /// Transport is shutting down.
 44→    Shutdown,
 45→
 46→    /// Invalid frame received.
 47→    InvalidFrame(String),
 48→
 49→    /// Handshake failed.
 50→    HandshakeFailed(String),
 51→
 52→    /// Identity verification failed during TLS handshake.
 53→    IdentityVerificationFailed {
 54→        reason: String,
 55→        claimed_node_id: String,
 56→    },
 57→
 58→    /// Certificate `NodeId` does not match claimed `NodeId`.
 59→    CertificateNodeIdMismatch {
 60→        cert_node_id: String,
 61→        claimed_node_id: String,
 62→    },
 63→
 64→    /// Client certificate required but not provided.
 65→    ClientCertificateRequired,
 66→
 67→    /// Compression/decompression error.
 68→    Compression {
 69→        operation: &'static str,
 70→        message: String,
 71→    },
 72→
 73→    /// Rate limited: peer is being sent messages too fast.
 74→    RateLimited { peer: String, available: u32 },
 75→
 76→    /// Connection pool exhausted: no healthy connections available.
 77→    PoolExhausted {
 78→        peer: String,
 79→        active: usize,
 80→        target: usize,
 81→    },
 82→
 83→    /// TLS is required by security mode but not configured.
 84→    TlsRequired { mode: SecurityMode, reason: String },
 85→
 86→    /// Mutual TLS (client auth) is required by security mode.
 87→    MtlsRequired { mode: SecurityMode, reason: String },
 88→
 89→    /// `NodeId` verification is required by security mode.
 90→    NodeIdVerificationRequired { mode: SecurityMode, reason: String },
 91→
 92→    /// Connection rejected: plaintext connection when TLS is required.
 93→    PlaintextRejected { remote_addr: String },
 94→
 95→    /// Connection rejected: no client certificate when mTLS is required.
 96→    ClientCertMissing { remote_addr: String },
 97→}
 98→
 99→impl fmt::Display for TcpError {
100→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
101→        match self {
102→            Self::ConnectionFailed { peer, reason } => {
103→                write!(f, "connection to {peer} failed: {reason}")
104→            },
105→            Self::ConnectionClosed => write!(f, "connection closed by peer"),
106→            Self::Timeout {
107→                operation,
108→                timeout_ms,
109→            } => {
110→                write!(f, "{operation} timed out after {timeout_ms}ms")
111→            },
112→            Self::MessageTooLarge { size, max_size } => {
113→                write!(f, "message too large: {size} bytes (max {max_size})")
114→            },
115→            Self::Serialization(msg) => write!(f, "serialization error: {msg}"),
116→            Self::Io(err) => write!(f, "io error: {err}"),
117→            Self::PeerNotFound(peer) => write!(f, "peer not found: {peer}"),
118→            Self::BackpressureFull { peer, queue_size } => {
119→                write!(
120→                    f,
121→                    "backpressure: queue full for {peer} ({queue_size} pending)"
122→                )
123→            },
124→            Self::TlsError(msg) => write!(f, "TLS error: {msg}"),
125→            Self::Shutdown => write!(f, "transport is shutting down"),
126→            Self::InvalidFrame(msg) => write!(f, "invalid frame: {msg}"),
127→            Self::HandshakeFailed(msg) => write!(f, "handshake failed: {msg}"),
128→            Self::IdentityVerificationFailed {
129→                reason,
130→                claimed_node_id,
131→            } => {
132→                write!(
133→                    f,
134→                    "identity verification failed for node '{claimed_node_id}': {reason}"
135→                )
136→            },
137→            Self::CertificateNodeIdMismatch {
138→                cert_node_id,
139→                claimed_node_id,
140→            } => {
141→                write!(f, "certificate NodeId mismatch: cert='{cert_node_id}', claimed='{claimed_node_id}'")
142→            },
143→            Self::ClientCertificateRequired => {
144→                write!(f, "client certificate required but not provided")
145→            },
146→            Self::Compression { operation, message } => {
147→                write!(f, "compression {operation} error: {message}")
148→            },
149→            Self::RateLimited { peer, available } => {
150→                write!(
151→                    f,
152→                    "rate limited: peer {peer} (available tokens: {available})"
153→                )
154→            },
155→            Self::PoolExhausted {
156→                peer,
157→                active,
158→                target,
159→            } => {
160→                write!(
161→                    f,
162→                    "pool exhausted for {peer}: {active}/{target} active connections"
163→                )
164→            },
165→            Self::TlsRequired { mode, reason } => {
166→                write!(f, "TLS required by security mode {mode:?}: {reason}")
167→            },
168→            Self::MtlsRequired { mode, reason } => {
169→                write!(f, "mutual TLS required by security mode {mode:?}: {reason}")
170→            },
171→            Self::NodeIdVerificationRequired { mode, reason } => {
172→                write!(
173→                    f,
174→                    "NodeId verification required by security mode {mode:?}: {reason}"
175→                )
176→            },
177→            Self::PlaintextRejected { remote_addr } => {
178→                write!(
179→                    f,
180→                    "plaintext connection rejected from {remote_addr}: TLS is required"
181→                )
182→            },
183→            Self::ClientCertMissing { remote_addr } => {
184→                write!(f, "connection from {remote_addr} rejected: client certificate required but not provided")
185→            },
186→        }
187→    }
188→}
