  1→//! Error types for the graph engine.
  2→
  3→use std::{
  4→    fmt,
  5→    hash::{Hash, Hasher},
  6→};
  7→
  8→use serde::{Deserialize, Serialize};
  9→
 10→/// Error type for graph operations.
 11→#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
 12→pub enum GraphError {
 13→    /// Node with the given ID was not found.
 14→    NodeNotFound(u64),
 15→    /// Edge with the given ID was not found.
 16→    EdgeNotFound(u64),
 17→    /// Underlying storage operation failed.
 18→    StorageError(String),
 19→    /// No path exists between the specified nodes.
 20→    PathNotFound,
 21→    /// Index already exists.
 22→    IndexAlreadyExists { target: String, property: String },
 23→    /// Index not found.
 24→    IndexNotFound { target: String, property: String },
 25→    /// Negative weight found during weighted path search.
 26→    NegativeWeight { edge_id: u64, weight: f64 },
 27→    /// Operation would violate a constraint.
 28→    ConstraintViolation {
 29→        constraint_name: String,
 30→        message: String,
 31→    },
 32→    /// Constraint with the given name already exists.
 33→    ConstraintAlreadyExists(String),
 34→    /// Constraint with the given name was not found.
 35→    ConstraintNotFound(String),
 36→    /// Batch validation failed at the given index.
 37→    BatchValidationError { index: usize, cause: Box<Self> },
 38→    /// Batch creation failed at the given index.
 39→    BatchCreationError { index: usize, cause: Box<Self> },
 40→    /// Node deletion partially failed (some edges could not be deleted).
 41→    PartialDeletionError {
 42→        node_id: u64,
 43→        failed_edges: Vec<u64>,
 44→    },
 45→    /// ID counter would overflow.
 46→    IdSpaceExhausted { entity_type: &'static str },
 47→    /// Invalid property name (contains reserved characters).
 48→    InvalidPropertyName { name: String },
 49→    /// Corrupted edge data.
 50→    CorruptedEdge { edge_id: u64, field: String },
 51→}
 52→
 53→impl fmt::Display for GraphError {
 54→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 55→        match self {
 56→            Self::NodeNotFound(id) => write!(f, "Node not found: {id}"),
 57→            Self::EdgeNotFound(id) => write!(f, "Edge not found: {id}"),
 58→            Self::StorageError(e) => write!(f, "Storage error: {e}"),
 59→            Self::PathNotFound => write!(f, "No path found between nodes"),
 60→            Self::IndexAlreadyExists { target, property } => {
 61→                write!(f, "Index already exists: {target}.{property}")
 62→            },
 63→            Self::IndexNotFound { target, property } => {
 64→                write!(f, "Index not found: {target}.{property}")
 65→            },
 66→            Self::NegativeWeight { edge_id, weight } => {
 67→                write!(f, "Edge {edge_id} has negative weight: {weight}")
 68→            },
 69→            Self::ConstraintViolation {
 70→                constraint_name,
 71→                message,
 72→            } => {
 73→                write!(f, "Constraint '{constraint_name}' violated: {message}")
 74→            },
 75→            Self::ConstraintAlreadyExists(name) => {
 76→                write!(f, "Constraint already exists: {name}")
 77→            },
 78→            Self::ConstraintNotFound(name) => write!(f, "Constraint not found: {name}"),
 79→            Self::BatchValidationError { index, cause } => {
 80→                write!(f, "Batch validation failed at index {index}: {cause}")
 81→            },
 82→            Self::BatchCreationError { index, cause } => {
 83→                write!(f, "Batch creation failed at index {index}: {cause}")
 84→            },
 85→            Self::PartialDeletionError {
 86→                node_id,
 87→                failed_edges,
 88→            } => {
 89→                write!(
 90→                    f,
 91→                    "Partial deletion of node {node_id}: {} edges failed to delete",
 92→                    failed_edges.len()
 93→                )
 94→            },
 95→            Self::IdSpaceExhausted { entity_type } => {
 96→                write!(f, "ID space exhausted for {entity_type}")
 97→            },
 98→            Self::InvalidPropertyName { name } => {
 99→                write!(
100→                    f,
101→                    "Invalid property name '{name}': contains reserved character ':'"
102→                )
103→            },
104→            Self::CorruptedEdge { edge_id, field } => {
105→                write!(
106→                    f,
107→                    "Corrupted edge {edge_id}: missing or invalid field '{field}'"
108→                )
109→            },
110→        }
111→    }
112→}
113→
114→impl std::error::Error for GraphError {}
115→
116→impl Eq for GraphError {}
117→
118→impl Hash for GraphError {
119→    fn hash<H: Hasher>(&self, state: &mut H) {
120→        std::mem::discriminant(self).hash(state);
121→        match self {
122→            Self::NodeNotFound(id) | Self::EdgeNotFound(id) => id.hash(state),
123→            Self::StorageError(s)
124→            | Self::ConstraintAlreadyExists(s)
125→            | Self::ConstraintNotFound(s) => s.hash(state),
126→            Self::PathNotFound => {},
127→            Self::IndexAlreadyExists { target, property }
128→            | Self::IndexNotFound { target, property } => {
129→                target.hash(state);
130→                property.hash(state);
131→            },
132→            Self::NegativeWeight { edge_id, weight } => {
133→                edge_id.hash(state);
134→                weight.to_bits().hash(state);
135→            },
136→            Self::ConstraintViolation {
137→                constraint_name,
138→                message,
139→            } => {
140→                constraint_name.hash(state);
141→                message.hash(state);
142→            },
143→            Self::BatchValidationError { index, cause }
144→            | Self::BatchCreationError { index, cause } => {
145→                index.hash(state);
146→                cause.hash(state);
147→            },
148→            Self::PartialDeletionError {
149→                node_id,
150→                failed_edges,
151→            } => {
152→                node_id.hash(state);
153→                failed_edges.hash(state);
154→            },
155→            Self::IdSpaceExhausted { entity_type } => {
156→                entity_type.hash(state);
157→            },
158→            Self::InvalidPropertyName { name } => {
159→                name.hash(state);
160→            },
161→            Self::CorruptedEdge { edge_id, field } => {
162→                edge_id.hash(state);
163→                field.hash(state);
164→            },
165→        }
166→    }
167→}
168→
169→impl From<tensor_store::TensorStoreError> for GraphError {
170→    fn from(e: tensor_store::TensorStoreError) -> Self {
171→        Self::StorageError(e.to_string())
172→    }
173→}
174→
175→/// Result type alias for graph operations.
176→pub type Result<T> = std::result::Result<T, GraphError>;
177→

  1→// SPDX-License-Identifier: MIT OR Apache-2.0
  2→//! Error types and diagnostics for the Neumann parser.
  3→//!
  4→//! Provides rich error messages with source context, including:
  5→//! - Precise source locations (line and column)
  6→//! - Error context with source snippets
  7→//! - Helpful suggestions and expected tokens
  8→
  9→use std::fmt;
 10→
 11→use crate::{
 12→    span::{get_line, line_col, Span},
 13→    token::TokenKind,
 14→};
 15→
 16→/// Result type for parser operations.
 17→pub type ParseResult<T> = Result<T, ParseError>;
 18→
 19→/// A parse error with source location.
 20→#[derive(Clone, Debug)]
 21→pub struct ParseError {
 22→    /// The kind of error.
 23→    pub kind: ParseErrorKind,
 24→    /// Where the error occurred.
 25→    pub span: Span,
 26→    /// Optional help message.
 27→    pub help: Option<String>,
 28→}
 29→
 30→impl ParseError {
 31→    /// Creates a new parse error.
 32→    #[must_use]
 33→    pub const fn new(kind: ParseErrorKind, span: Span) -> Self {
 34→        Self {
 35→            kind,
 36→            span,
 37→            help: None,
 38→        }
 39→    }
 40→
 41→    /// Creates an "unexpected token" error.
 42→    pub fn unexpected(found: TokenKind, span: Span, expected: impl Into<String>) -> Self {
 43→        Self::new(
 44→            ParseErrorKind::UnexpectedToken {
 45→                found,
 46→                expected: expected.into(),
 47→            },
 48→            span,
 49→        )
 50→    }
 51→
 52→    /// Creates an "unexpected EOF" error.
 53→    pub fn unexpected_eof(span: Span, expected: impl Into<String>) -> Self {
 54→        Self::new(
 55→            ParseErrorKind::UnexpectedEof {
 56→                expected: expected.into(),
 57→            },
 58→            span,
 59→        )
 60→    }
 61→
 62→    /// Creates an "invalid syntax" error.
 63→    pub fn invalid(message: impl Into<String>, span: Span) -> Self {
 64→        Self::new(ParseErrorKind::InvalidSyntax(message.into()), span)
 65→    }
 66→
 67→    /// Adds a help message to the error.
 68→    #[must_use]
 69→    pub fn with_help(mut self, help: impl Into<String>) -> Self {
 70→        self.help = Some(help.into());
 71→        self
 72→    }
 73→
 74→    /// Formats the error with source context.
 75→    #[must_use]
 76→    #[allow(clippy::format_push_string)]
 77→    pub fn format_with_source(&self, source: &str) -> String {
 78→        let (line, col) = line_col(source, self.span.start);
 79→        let line_text = get_line(source, self.span.start);
 80→
 81→        let kind = &self.kind;
 82→        let mut result = format!("error: {kind}\n");
 83→        result.push_str(&format!("  --> line {line}:{col}\n"));
 84→        result.push_str("   |\n");
 85→        result.push_str(&format!("{line:3} | {line_text}\n"));
 86→        result.push_str("   | ");
 87→
 88→        // Add carets under the error
 89→        for _ in 0..(col - 1) {
 90→            result.push(' ');
 91→        }
 92→        let len = self.span.len().max(1) as usize;
 93→        let caret_len = len.min(line_text.len().saturating_sub(col - 1));
 94→        for _ in 0..caret_len.max(1) {
 95→            result.push('^');
 96→        }
 97→        result.push('\n');
 98→
 99→        if let Some(help) = &self.help {
100→            result.push_str(&format!("   = help: {help}\n"));
101→        }
102→
103→        result
104→    }
105→}
106→
107→impl fmt::Display for ParseError {
108→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
109→        write!(f, "{} at {}", self.kind, self.span)
110→    }
111→}
112→
113→impl std::error::Error for ParseError {}
114→
115→/// Parse error kinds.
116→#[derive(Clone, Debug)]
117→pub enum ParseErrorKind {
118→    /// Unexpected token
119→    UnexpectedToken {
120→        /// The token that was found.
121→        found: TokenKind,
122→        /// Description of what was expected.
123→        expected: String,
124→    },
125→    /// Unexpected end of input
126→    UnexpectedEof {
127→        /// Description of what was expected.
128→        expected: String,
129→    },
130→    /// Invalid syntax
131→    InvalidSyntax(String),
132→    /// Invalid number
133→    InvalidNumber(String),
134→    /// Unterminated string
135→    UnterminatedString,
136→    /// Unknown keyword or command
137→    UnknownCommand(String),
138→    /// Duplicate column
139→    DuplicateColumn(String),
140→    /// Invalid escape sequence
141→    InvalidEscape(char),
142→    /// Expression too deeply nested
143→    TooDeep,
144→    /// Custom error
145→    Custom(String),
146→}
147→
148→impl fmt::Display for ParseErrorKind {
149→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
150→        match self {
151→            Self::UnexpectedToken { found, expected } => {
152→                write!(f, "unexpected {found}, expected {expected}")
153→            },
154→            Self::UnexpectedEof { expected } => {
155→                write!(f, "unexpected end of input, expected {expected}")
156→            },
157→            Self::InvalidSyntax(msg) | Self::Custom(msg) => write!(f, "{msg}"),
158→            Self::InvalidNumber(msg) => write!(f, "invalid number: {msg}"),
159→            Self::UnterminatedString => write!(f, "unterminated string literal"),
160→            Self::UnknownCommand(cmd) => write!(f, "unknown command: {cmd}"),
161→            Self::DuplicateColumn(col) => write!(f, "duplicate column: {col}"),
162→            Self::InvalidEscape(c) => write!(f, "invalid escape sequence: \\{c}"),
163→            Self::TooDeep => write!(f, "expression nesting too deep"),
164→        }
165→    }
166→}
167→
168→/// A collection of parse errors.
169→#[derive(Clone, Debug, Default)]
170→pub struct Errors {
171→    errors: Vec<ParseError>,
172→}
173→
174→impl Errors {
175→    /// Creates an empty error collection.
176→    #[must_use]
177→    pub const fn new() -> Self {
178→        Self { errors: Vec::new() }
179→    }
180→
181→    /// Adds an error to the collection.
182→    pub fn push(&mut self, error: ParseError) {
183→        self.errors.push(error);
184→    }
185→
186→    /// Returns true if there are no errors.
187→    #[must_use]
188→    pub const fn is_empty(&self) -> bool {
189→        self.errors.is_empty()
190→    }
191→
192→    /// Returns the number of errors.
193→    #[must_use]
194→    pub const fn len(&self) -> usize {
195→        self.errors.len()
196→    }
197→
198→    /// Returns an iterator over the errors.
199→    pub fn iter(&self) -> impl Iterator<Item = &ParseError> {
200→        self.errors.iter()
201→    }
202→
203→    /// Consumes the collection and returns the errors.
204→    #[must_use]
205→    pub fn into_vec(self) -> Vec<ParseError> {
206→        self.errors
207→    }
208→
209→    /// Formats all errors with source context.
210→    #[must_use]
211→    pub fn format_with_source(&self, source: &str) -> String {
212→        self.errors
213→            .iter()
214→            .map(|e| e.format_with_source(source))
215→            .collect::<Vec<_>>()
216→            .join("\n")
217→    }
218→}
219→
220→impl IntoIterator for Errors {
221→    type Item = ParseError;
222→    type IntoIter = std::vec::IntoIter<ParseError>;
223→
224→    fn into_iter(self) -> Self::IntoIter {
225→        self.errors.into_iter()
226→    }
227→}
228→
229→impl<'a> IntoIterator for &'a Errors {
230→    type Item = &'a ParseError;
231→    type IntoIter = std::slice::Iter<'a, ParseError>;
232→
233→    fn into_iter(self) -> Self::IntoIter {
234→        self.errors.iter()
235→    }
236→}
237→
238→impl Extend<ParseError> for Errors {
239→    fn extend<T: IntoIterator<Item = ParseError>>(&mut self, iter: T) {
240→        self.errors.extend(iter);
241→    }
242→}
243→
244→impl FromIterator<ParseError> for Errors {
245→    fn from_iter<T: IntoIterator<Item = ParseError>>(iter: T) -> Self {
246→        Self {
247→            errors: iter.into_iter().collect(),
248→        }
249→    }
250→}
