 2→//! Synchronization compatibility for loom testing.
 3→//!
 4→//! Re-exports `parking_lot::RwLock` and `parking_lot::Mutex` in normal builds
 5→//! and provides thin wrappers around `loom::sync` equivalents when the `loom`
 6→//! feature is active. The wrappers strip the `Result` returns from loom's API
 7→//! so call sites stay identical.
 8→
 9→#[cfg(not(feature = "loom"))]
10→pub use parking_lot::{Mutex, RwLock};
11→
12→#[cfg(feature = "loom")]
13→pub use self::loom_compat::{Mutex, RwLock};
14→
15→#[cfg(feature = "loom")]
16→mod loom_compat {
17→    use std::fmt;
18→
19→    /// Thin wrapper matching `parking_lot::RwLock` API (no `Result` from read/write).
20→    pub struct RwLock<T>(loom::sync::RwLock<T>);
21→
22→    impl<T> RwLock<T> {
23→        pub fn new(t: T) -> Self {
24→            Self(loom::sync::RwLock::new(t))
25→        }
26→
27→        pub fn read(&self) -> loom::sync::RwLockReadGuard<'_, T> {
28→            self.0.read().unwrap()
29→        }
30→
31→        pub fn write(&self) -> loom::sync::RwLockWriteGuard<'_, T> {
32→            self.0.write().unwrap()
33→        }
34→    }
35→
36→    impl<T: Default> Default for RwLock<T> {
37→        fn default() -> Self {
38→            Self::new(T::default())
39→        }
40→    }
41→
42→    impl<T: fmt::Debug> fmt::Debug for RwLock<T> {
43→        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
44→            match self.0.try_read() {
45→                Ok(guard) => f.debug_tuple("RwLock").field(&*guard).finish(),
46→                Err(_) => f.debug_tuple("RwLock").field(&"<locked>").finish(),
47→            }
48→        }
49→    }
50→
51→    /// Thin wrapper matching `parking_lot::Mutex` API (no `Result` from lock).
52→    pub struct Mutex<T>(loom::sync::Mutex<T>);
53→
54→    impl<T> Mutex<T> {
55→        pub fn new(t: T) -> Self {
56→            Self(loom::sync::Mutex::new(t))
57→        }
58→
59→        pub fn lock(&self) -> loom::sync::MutexGuard<'_, T> {
60→            self.0.lock().unwrap()
61→        }
62→    }
63→
64→    impl<T: Default> Default for Mutex<T> {
65→        fn default() -> Self {
66→            Self::new(T::default())
67→        }
68→    }
69→
70→    impl<T: fmt::Debug> fmt::Debug for Mutex<T> {
71→        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
72→            match self.0.try_lock() {
73→                Ok(guard) => f.debug_tuple("Mutex").field(&*guard).finish(),
74→                Err(_) => f.debug_tuple("Mutex").field(&"<locked>").finish(),
75→            }
76→        }
77→    }
78→}
