 33→
 34→impl fmt::Display for BlobError {
 35→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 36→        match self {
 37→            Self::NotFound(id) => write!(f, "artifact not found: {id}"),
 38→            Self::ChunkMissing(hash) => write!(f, "chunk missing: {hash}"),
 39→            Self::ChecksumMismatch { expected, actual } => {
 40→                write!(f, "checksum mismatch: expected {expected}, got {actual}")
 41→            },
 42→            Self::StorageError(msg) => write!(f, "storage error: {msg}"),
 43→            Self::GraphError(msg) => write!(f, "graph error: {msg}"),
 44→            Self::VectorError(msg) => write!(f, "vector error: {msg}"),
 45→            Self::InvalidArtifactId(id) => write!(f, "invalid artifact id: {id}"),
 46→            Self::InvalidConfig(msg) => write!(f, "invalid config: {msg}"),
 47→            Self::IoError(msg) => write!(f, "io error: {msg}"),
 48→            Self::GcError(msg) => write!(f, "gc error: {msg}"),
 49→            Self::AlreadyExists(id) => write!(f, "artifact already exists: {id}"),
 50→            Self::EmptyData => write!(f, "empty data provided"),
 51→            Self::DimensionMismatch { expected, got } => {
 52→                write!(f, "dimension mismatch: expected {expected}, got {got}")
 53→            },
 54→        }
 55→    }
 56→}
