  2→//! TTL (Time-To-Live) tracking for vault grants.
  3→//!
  4→//! Enables time-limited access grants that automatically expire.
  5→//! Supports persistence for survival across restarts.
  6→
  7→#![allow(clippy::missing_panics_doc)]
  8→
  9→use std::{
 10→    cmp::Ordering,
 11→    collections::BinaryHeap,
 12→    sync::Mutex,
 13→    time::{Duration, Instant, SystemTime, UNIX_EPOCH},
 14→};
 15→
 16→use serde::{Deserialize, Serialize};
 17→use tensor_store::TensorStore;
 18→
 19→use crate::{Result, VaultError};
 20→
 21→/// Storage key for persisted TTL grants.
 22→const TTL_STORAGE_KEY: &str = "_vault_ttl_grants";
 23→
 24→/// Serializable grant expiration for persistence.
 25→#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
 26→pub struct PersistedGrant {
 27→    /// Unix timestamp (milliseconds) when this grant expires.
 28→    pub expires_at_ms: i64,
 29→    /// The entity that was granted access.
 30→    pub entity: String,
 31→    /// The secret key.
 32→    pub secret_key: String,
 33→}
 34→
 35→/// An entry in the grant TTL tracker.
 36→#[derive(Debug, Clone)]
 37→struct GrantTTLEntry {
 38→    /// When this grant expires.
 39→    expires_at: Instant,
 40→    /// The entity that was granted access.
 41→    entity: String,
 42→    /// The secret key.
 43→    secret_key: String,
 44→}
 45→
 46→impl PartialEq for GrantTTLEntry {
 47→    fn eq(&self, other: &Self) -> bool {
 48→        self.expires_at == other.expires_at
 49→            && self.entity == other.entity
 50→            && self.secret_key == other.secret_key
 51→    }
 52→}
 53→
 54→impl Eq for GrantTTLEntry {}
 55→
 56→impl PartialOrd for GrantTTLEntry {
 57→    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
 58→        Some(self.cmp(other))
 59→    }
 60→}
 61→
 62→impl Ord for GrantTTLEntry {
 63→    fn cmp(&self, other: &Self) -> Ordering {
 64→        // Reverse order for min-heap (earliest expiration first)
 65→        other.expires_at.cmp(&self.expires_at)
 66→    }
 67→}
 68→
 69→/// Tracks grant expiration times for automatic revocation.
 70→pub struct GrantTTLTracker {
 71→    /// Priority queue of expiration times (min-heap).
 72→    heap: Mutex<BinaryHeap<GrantTTLEntry>>,
 73→}
 74→
 75→impl GrantTTLTracker {
 76→    /// Create a new grant TTL tracker.
 77→    pub fn new() -> Self {
 78→        Self {
 79→            heap: Mutex::new(BinaryHeap::new()),
 80→        }
 81→    }
 82→
 83→    /// Add a grant to the tracker with the specified TTL.
 84→    pub fn add(&self, entity: &str, secret_key: &str, ttl: Duration) {
 85→        let entry = GrantTTLEntry {
 86→            expires_at: Instant::now() + ttl,
 87→            entity: entity.to_string(),
 88→            secret_key: secret_key.to_string(),
 89→        };
 90→        self.heap.lock().unwrap().push(entry);
 91→    }
 92→
 93→    /// Add a grant with an explicit expiration time.
 94→    pub fn add_with_expiration(&self, entity: &str, secret_key: &str, expires_at: Instant) {
 95→        let entry = GrantTTLEntry {
 96→            expires_at,
 97→            entity: entity.to_string(),
 98→            secret_key: secret_key.to_string(),
 99→        };
100→        self.heap.lock().unwrap().push(entry);
101→    }
102→
103→    /// Get all expired grants.
104→    ///
105→    /// Returns a list of (entity, secret_key) pairs for grants that have expired.
106→    /// These entries are removed from the tracker.
107→    pub fn get_expired(&self) -> Vec<(String, String)> {
108→        let now = Instant::now();
109→        let mut expired = Vec::new();
110→        let mut heap = self.heap.lock().unwrap();
111→
112→        while let Some(entry) = heap.peek() {
113→            if entry.expires_at <= now {
114→                if let Some(entry) = heap.pop() {
115→                    expired.push((entry.entity, entry.secret_key));
116→                }
117→            } else {
118→                break;
119→            }
120→        }
121→
122→        expired
123→    }
124→
125→    /// Get the number of grants being tracked.
126→    pub fn len(&self) -> usize {
127→        self.heap.lock().unwrap().len()
128→    }
129→
130→    /// Check if the tracker is empty.
131→    pub fn is_empty(&self) -> bool {
132→        self.heap.lock().unwrap().is_empty()
133→    }
134→
135→    /// Clear all entries.
136→    pub fn clear(&self) {
137→        self.heap.lock().unwrap().clear();
138→    }
139→
140→    /// Get the next expiration time, if any.
141→    pub fn next_expiration(&self) -> Option<Instant> {
142→        self.heap.lock().unwrap().peek().map(|e| e.expires_at)
143→    }
144→
145→    /// Check if a specific grant is expired.
146→    ///
147→    /// Note: This does a linear search and is O(n). For bulk checks,
148→    /// use `get_expired()` instead.
149→    #[allow(clippy::significant_drop_tightening)]
150→    pub fn is_expired(&self, entity: &str, secret_key: &str) -> bool {
151→        let now = Instant::now();
152→        let heap = self.heap.lock().unwrap();
153→
154→        for entry in heap.iter() {
155→            if entry.entity == entity && entry.secret_key == secret_key {
156→                return entry.expires_at <= now;
157→            }
158→        }
159→
160→        // Not found in tracker = not tracked, so not expired by TTL
161→        false
162→    }
163→
164→    /// Remove a specific grant from tracking (e.g., when manually revoked).
165→    ///
166→    /// Returns true if the grant was found and removed.
167→    pub fn remove(&self, entity: &str, secret_key: &str) -> bool {
168→        let mut heap = self.heap.lock().unwrap();
169→        let original_len = heap.len();
170→
171→        let entries: Vec<GrantTTLEntry> = heap
172→            .drain()
173→            .filter(|e| !(e.entity == entity && e.secret_key == secret_key))
174→            .collect();
175→
176→        let removed = entries.len() < original_len;
177→        for entry in entries {
178→            heap.push(entry);
179→        }
180→
181→        removed
182→    }
183→
184→    /// Convert an Instant to Unix timestamp milliseconds.
185→    fn instant_to_unix_ms(instant: Instant) -> i64 {
186→        let now = Instant::now();
187→        let now_unix = SystemTime::now()
188→            .duration_since(UNIX_EPOCH)
189→            .map(|d| d.as_millis() as i64)
190→            .unwrap_or(0);
191→
192→        // Calculate the difference and apply to current Unix time
193→        if instant > now {
194→            let delta = (instant - now).as_millis() as i64;
195→            now_unix + delta
196→        } else {
197→            let delta = (now - instant).as_millis() as i64;
198→            now_unix - delta
199→        }
200→    }
201→
202→    /// Convert Unix timestamp milliseconds to an Instant.
203→    fn unix_ms_to_instant(unix_ms: i64) -> Instant {
204→        let now = Instant::now();
205→        let now_unix = SystemTime::now()
206→            .duration_since(UNIX_EPOCH)
207→            .map(|d| d.as_millis() as i64)
208→            .unwrap_or(0);
209→
210→        let delta = unix_ms - now_unix;
211→        if delta >= 0 {
212→            // Safe: delta is guaranteed non-negative here
213→            now + Duration::from_millis(delta.unsigned_abs())
214→        } else {
215→            // Safe: we're subtracting a duration that was computed from the clock difference
216→            now.checked_sub(Duration::from_millis(delta.unsigned_abs()))
217→                .unwrap_or(now)
218→        }
219→    }
220→
221→    /// Persist all grants to the store.
222→    pub fn persist(&self, store: &TensorStore) -> Result<()> {
223→        // Collect grants while holding the lock, then release it
224→        let grants: Vec<PersistedGrant> = {
225→            let heap = self.heap.lock().unwrap();
226→            heap.iter()
227→                .map(|e| PersistedGrant {
228→                    expires_at_ms: Self::instant_to_unix_ms(e.expires_at),
229→                    entity: e.entity.clone(),
230→                    secret_key: e.secret_key.clone(),
231→                })
232→                .collect()
233→        };
234→
235→        if grants.is_empty() {
236→            // Remove the storage key if no grants - may not exist, delete is idempotent
237→            store.delete(TTL_STORAGE_KEY).ok();
238→            return Ok(());
239→        }
240→
241→        let data = serde_json::to_vec(&grants)
242→            .map_err(|e| VaultError::CryptoError(format!("Failed to serialize TTL grants: {e}")))?;
243→
244→        let mut tensor = tensor_store::TensorData::new();
245→        tensor.set(
246→            "_data",
247→            tensor_store::TensorValue::Scalar(tensor_store::ScalarValue::Bytes(data)),
248→        );
249→        store
250→            .put(TTL_STORAGE_KEY, tensor)
251→            .map_err(|e| VaultError::CryptoError(format!("Failed to persist TTL grants: {e}")))?;
252→
253→        Ok(())
254→    }
255→
256→    /// Load grants from the store.
257→    /// Returns a new tracker with the loaded grants.
258→    pub fn load(store: &TensorStore) -> Result<Self> {
259→        let tracker = Self::new();
260→
261→        let Ok(tensor) = store.get(TTL_STORAGE_KEY) else {
262→            return Ok(tracker); // Key not found, return empty tracker
263→        };
264→
265→        let Some(tensor_store::TensorValue::Scalar(tensor_store::ScalarValue::Bytes(data))) =
266→            tensor.get("_data")
267→        else {
268→            return Ok(tracker);
269→        };
270→
271→        let grants: Vec<PersistedGrant> = serde_json::from_slice(data).map_err(|e| {
272→            VaultError::CryptoError(format!("Failed to deserialize TTL grants: {e}"))
273→        })?;
274→
275→        {
276→            let mut heap = tracker.heap.lock().unwrap();
277→            for grant in grants {
278→                heap.push(GrantTTLEntry {
279→                    expires_at: Self::unix_ms_to_instant(grant.expires_at_ms),
280→                    entity: grant.entity,
281→                    secret_key: grant.secret_key,
282→                });
283→            }
284→        }
285→
286→        Ok(tracker)
287→    }
288→
289→    /// Get all grants as serializable format for persistence.
290→    pub fn to_persisted(&self) -> Vec<PersistedGrant> {
291→        let heap = self.heap.lock().unwrap();
292→        heap.iter()
293→            .map(|e| PersistedGrant {
294→                expires_at_ms: Self::instant_to_unix_ms(e.expires_at),
295→                entity: e.entity.clone(),
296→                secret_key: e.secret_key.clone(),
297→            })
298→            .collect()
299→    }
300→}
301→
302→impl Default for GrantTTLTracker {
303→    fn default() -> Self {
304→        Self::new()
305→    }
306→}
