 48→
 49→    /// Handshake failed.
 50→    HandshakeFailed(String),
 51→
 52→    /// Identity verification failed during TLS handshake.
 53→    IdentityVerificationFailed {
 54→        reason: String,
 55→        claimed_node_id: String,
 56→    },
 57→
