 71→    },
 72→
 73→    /// Rate limited: peer is being sent messages too fast.
 74→    RateLimited { peer: String, available: u32 },
 75→
 76→    /// Connection pool exhausted: no healthy connections available.
 77→    PoolExhausted {
 78→        peer: String,
 79→        active: usize,
 80→        target: usize,
 81→    },
 82→
 83→    /// TLS is required by security mode but not configured.
 84→    TlsRequired { mode: SecurityMode, reason: String },
