 99→impl fmt::Display for TcpError {
100→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
101→        match self {
102→            Self::ConnectionFailed { peer, reason } => {
103→                write!(f, "connection to {peer} failed: {reason}")
104→            },
105→            Self::ConnectionClosed => write!(f, "connection closed by peer"),
106→            Self::Timeout {
107→                operation,
108→                timeout_ms,
109→            } => {
110→                write!(f, "{operation} timed out after {timeout_ms}ms")
111→            },
112→            Self::MessageTooLarge { size, max_size } => {
113→                write!(f, "message too large: {size} bytes (max {max_size})")
114→            },
115→            Self::Serialization(msg) => write!(f, "serialization error: {msg}"),
116→            Self::Io(err) => write!(f, "io error: {err}"),
117→            Self::PeerNotFound(peer) => write!(f, "peer not found: {peer}"),
118→            Self::BackpressureFull { peer, queue_size } => {
119→                write!(
120→                    f,
121→                    "backpressure: queue full for {peer} ({queue_size} pending)"
122→                )
123→            },
124→            Self::TlsError(msg) => write!(f, "TLS error: {msg}"),
125→            Self::Shutdown => write!(f, "transport is shutting down"),
126→            Self::InvalidFrame(msg) => write!(f, "invalid frame: {msg}"),
127→            Self::HandshakeFailed(msg) => write!(f, "handshake failed: {msg}"),
128→            Self::IdentityVerificationFailed {
129→                reason,
130→                claimed_node_id,
131→            } => {
132→                write!(
133→                    f,
134→                    "identity verification failed for node '{claimed_node_id}': {reason}"
135→                )
136→            },
137→            Self::CertificateNodeIdMismatch {
138→                cert_node_id,
139→                claimed_node_id,
140→            } => {
141→                write!(f, "certificate NodeId mismatch: cert='{cert_node_id}', claimed='{claimed_node_id}'")
142→            },
143→            Self::ClientCertificateRequired => {
144→                write!(f, "client certificate required but not provided")
145→            },
146→            Self::Compression { operation, message } => {
147→                write!(f, "compression {operation} error: {message}")
148→            },
149→            Self::RateLimited { peer, available } => {
150→                write!(
151→                    f,
152→                    "rate limited: peer {peer} (available tokens: {available})"
153→                )
154→            },
155→            Self::PoolExhausted {
156→                peer,
157→                active,
158→                target,
159→            } => {
160→                write!(
161→                    f,
162→                    "pool exhausted for {peer}: {active}/{target} active connections"
163→                )
164→            },
165→            Self::TlsRequired { mode, reason } => {
166→                write!(f, "TLS required by security mode {mode:?}: {reason}")
167→            },
168→            Self::MtlsRequired { mode, reason } => {
169→                write!(f, "mutual TLS required by security mode {mode:?}: {reason}")
170→            },
171→            Self::NodeIdVerificationRequired { mode, reason } => {
172→                write!(
173→                    f,
174→                    "NodeId verification required by security mode {mode:?}: {reason}"
175→                )
176→            },
177→            Self::PlaintextRejected { remote_addr } => {
178→                write!(
179→                    f,
180→                    "plaintext connection rejected from {remote_addr}: TLS is required"
181→                )
182→            },
183→            Self::ClientCertMissing { remote_addr } => {
184→                write!(f, "connection from {remote_addr} rejected: client certificate required but not provided")
185→            },
186→        }
187→    }
188→}
