127→/// Permission levels for vault access.
128→#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
129→pub enum Permission {
130→    /// Read-only access: can get(), list()
131→    #[default]
132→    Read,
133→    /// Write access: can get(), list(), set(), rotate()
134→    Write,
135→    /// Admin access: can get(), list(), set(), rotate(), delete(), grant(), revoke()
136→    Admin,
137→}
138→
139→impl Permission {
140→    /// Check if this permission level allows the given operation.
141→    pub fn allows(&self, required: Self) -> bool {
142→        matches!(
143→            (self, required),
144→            (Self::Admin, _) | (Self::Write, Self::Read | Self::Write) | (Self::Read, Self::Read)
145→        )
146→    }
147→
148→    /// Numeric level for bottleneck flow (1=Read, 2=Write, 3=Admin).
149→    pub(crate) fn to_level(self) -> i64 {
150→        match self {
151→            Self::Read => 1,
152→            Self::Write => 2,
153→            Self::Admin => 3,
154→        }
155→    }
156→
157→    /// Parse from numeric level.
158→    pub(crate) fn from_level(level: i64) -> Option<Self> {
159→        match level {
160→            1 => Some(Self::Read),
161→            2 => Some(Self::Write),
162→            3 => Some(Self::Admin),
163→            _ => None,
164→        }
165→    }
166→
167→    /// Get edge type suffix for this permission level.
168→    pub(crate) fn edge_suffix(self) -> &'static str {
169→        match self {
170→            Self::Read => "_READ",
171→            Self::Write => "_WRITE",
172→            Self::Admin => "_ADMIN",
173→        }
174→    }
175→
176→    /// Parse from edge type.
177→    pub(crate) fn from_edge_type(edge_type: &str) -> Option<Self> {
178→        if edge_type.ends_with("_READ") {
179→            Some(Self::Read)
180→        } else if edge_type.ends_with("_WRITE") {
181→            Some(Self::Write)
182→        } else if edge_type.ends_with("_ADMIN") {
183→            Some(Self::Admin)
184→        } else if edge_type == "VAULT_ACCESS" {
185→            // Backward compatibility: old grants are Admin
186→            Some(Self::Admin)
187→        } else {
188→            None
189→        }
190→    }
191→}
192→
193→impl std::fmt::Display for Permission {
194→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
195→        match self {
196→            Self::Read => write!(f, "READ"),
197→            Self::Write => write!(f, "WRITE"),
198→            Self::Admin => write!(f, "ADMIN"),
199→        }

