//! Error types for the graph engine.

use std::{
    fmt,
    hash::{Hash, Hasher},
};

use serde::{Deserialize, Serialize};

/// Error type for graph operations.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum GraphError {
    /// Node with the given ID was not found.
    NodeNotFound(u64),
    /// Edge with the given ID was not found.
    EdgeNotFound(u64),
    /// Underlying storage operation failed.
    StorageError(String),
    /// No path exists between the specified nodes.
    PathNotFound,
    /// Index already exists.
    IndexAlreadyExists { target: String, property: String },
    /// Index not found.
    IndexNotFound { target: String, property: String },
    /// Negative weight found during weighted path search.
    NegativeWeight { edge_id: u64, weight: f64 },
    /// Operation would violate a constraint.
    ConstraintViolation {
        constraint_name: String,
        message: String,
    },
    /// Constraint with the given name already exists.
    ConstraintAlreadyExists(String),
    /// Constraint with the given name was not found.
    ConstraintNotFound(String),
    /// Batch validation failed at the given index.
    BatchValidationError { index: usize, cause: Box<Self> },
    /// Batch creation failed at the given index.
    BatchCreationError { index: usize, cause: Box<Self> },
    /// Node deletion partially failed (some edges could not be deleted).
    PartialDeletionError {
        node_id: u64,
        failed_edges: Vec<u64>,
    },
    /// ID counter would overflow.
    IdSpaceExhausted { entity_type: &'static str },
    /// Invalid property name (contains reserved characters).
    InvalidPropertyName { name: String },
    /// Corrupted edge data.
    CorruptedEdge { edge_id: u64, field: String },
}

impl fmt::Display for GraphError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::NodeNotFound(id) => write!(f, "Node not found: {id}"),
            Self::EdgeNotFound(id) => write!(f, "Edge not found: {id}"),
            Self::StorageError(e) => write!(f, "Storage error: {e}"),
            Self::PathNotFound => write!(f, "No path found between nodes"),
            Self::IndexAlreadyExists { target, property } => {
                write!(f, "Index already exists: {target}.{property}")
            },
            Self::IndexNotFound { target, property } => {
                write!(f, "Index not found: {target}.{property}")
            },
            Self::NegativeWeight { edge_id, weight } => {
                write!(f, "Edge {edge_id} has negative weight: {weight}")
            },
            Self::ConstraintViolation {
                constraint_name,
                message,
            } => {
                write!(f, "Constraint '{constraint_name}' violated: {message}")
            },
            Self::ConstraintAlreadyExists(name) => {
                write!(f, "Constraint already exists: {name}")
            },
            Self::ConstraintNotFound(name) => write!(f, "Constraint not found: {name}"),
            Self::BatchValidationError { index, cause } => {
                write!(f, "Batch validation failed at index {index}: {cause}")
            },
            Self::BatchCreationError { index, cause } => {
                write!(f, "Batch creation failed at index {index}: {cause}")
            },
            Self::PartialDeletionError {
                node_id,
                failed_edges,
            } => {
                write!(
                    f,
                    "Partial deletion of node {node_id}: {} edges failed to delete",
                    failed_edges.len()
                )
            },
            Self::IdSpaceExhausted { entity_type } => {
                write!(f, "ID space exhausted for {entity_type}")
            },
            Self::InvalidPropertyName { name } => {
                write!(
                    f,
                    "Invalid property name '{name}': contains reserved character ':'"
                )
            },
            Self::CorruptedEdge { edge_id, field } => {
                write!(
                    f,
                    "Corrupted edge {edge_id}: missing or invalid field '{field}'"
                )
            },
        }
    }
}

impl std::error::Error for GraphError {}

impl Eq for GraphError {}

impl Hash for GraphError {
    fn hash<H: Hasher>(&self, state: &mut H) {
        std::mem::discriminant(self).hash(state);
        match self {
            Self::NodeNotFound(id) | Self::EdgeNotFound(id) => id.hash(state),
            Self::StorageError(s)
            | Self::ConstraintAlreadyExists(s)
            | Self::ConstraintNotFound(s) => s.hash(state),
            Self::PathNotFound => {},
            Self::IndexAlreadyExists { target, property }
            | Self::IndexNotFound { target, property } => {
                target.hash(state);
                property.hash(state);
            },
            Self::NegativeWeight { edge_id, weight } => {
                edge_id.hash(state);
                weight.to_bits().hash(state);
            },
            Self::ConstraintViolation {
                constraint_name,
                message,
            } => {
                constraint_name.hash(state);
                message.hash(state);
            },
            Self::BatchValidationError { index, cause }
            | Self::BatchCreationError { index, cause } => {
                index.hash(state);
                cause.hash(state);
            },
            Self::PartialDeletionError {
                node_id,
                failed_edges,
            } => {
                node_id.hash(state);
                failed_edges.hash(state);
            },
            Self::IdSpaceExhausted { entity_type } => {
                entity_type.hash(state);
            },
            Self::InvalidPropertyName { name } => {
                name.hash(state);
            },
            Self::CorruptedEdge { edge_id, field } => {
                edge_id.hash(state);
                field.hash(state);
            },
        }
    }
}

impl From<tensor_store::TensorStoreError> for GraphError {
    fn from(e: tensor_store::TensorStoreError) -> Self {
        Self::StorageError(e.to_string())
    }
}

/// Result type alias for graph operations.
pub type Result<T> = std::result::Result<T, GraphError>;

//! R-tree spatial index for region and nearest-neighbor queries.
//!
//! Provides a generic N-dimensional R-tree with linear and R\*-tree split
//! algorithms, supporting insertion, removal, region queries, radius queries,
//! and k-nearest-neighbor lookups. The core types are parameterized by
//! `const D: usize` for the spatial dimension and `T` for user data.
//!
//! Type aliases preserve the existing 2D and 3D API:
//! - [`BoundingBox`] = `BoundingBoxN<2>`
//! - [`BoundingBox3D`] = `BoundingBoxN<3>`
//! - [`SpatialEntry`] = `SpatialEntryN<2, T>`
//! - [`SpatialEntry3D`] = `SpatialEntryN<3, T>`
//! - [`SpatialIndex`] = `SpatialIndexN<2, T>`
//! - [`SpatialIndex3D`] = `SpatialIndexN<3, T>`
//!
//! ## Concurrency
//!
//! `SpatialIndexN` has no internal synchronization. For concurrent access,
//! wrap it in `Arc<parking_lot::RwLock<>>`:
//!
//! ```rust,ignore
//! use std::sync::Arc;
//! use parking_lot::RwLock;
//! use tensor_spatial::{SpatialIndex, SpatialEntry, BoundingBox};
//!
//! let index = Arc::new(RwLock::new(SpatialIndex::<String>::new()));
//!
//! // Read access (multiple concurrent readers allowed):
//! let region = BoundingBox::new(0.0, 0.0, 10.0, 10.0).unwrap();
//! let results = index.read().query_region(region);
//!
//! // Write access (exclusive):
//! index.write().insert(SpatialEntry {
//!     bounds: BoundingBox::new(1.0, 2.0, 1.0, 1.0).unwrap(),
//!     data: "item".to_string(),
//! });
//! ```

mod bbox;
mod index;
mod iter;
mod node;

pub use bbox::{BoundingBoxN, SpatialEntryN};
pub use index::SpatialIndexN;
pub use iter::SpatialIterN;

/// Default maximum entries per R-tree node before splitting.
const DEFAULT_MAX_ENTRIES: usize = 9;

/// Default minimum entries per R-tree node after splitting.
const DEFAULT_MIN_ENTRIES: usize = 4;

/// Split strategy for R-tree overflow handling.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum SplitStrategy {
    /// Linear split: O(n^2) seed selection, greedy distribution.
    Linear = 0,
    /// R\*-tree: axis-based split, overlap-minimizing, forced reinsertion.
    #[default]
    RStar = 1,
}

/// Configuration for R-tree node capacity and split behavior.
///
/// Controls the maximum and minimum number of entries per node. Construction
/// is validated to ensure `max_entries >= 4` and `min_entries = max_entries / 2`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SpatialConfig {
    /// Maximum entries per node before splitting.
    max_entries: usize,
    /// Minimum entries per node; underflow triggers `condense_tree`.
    min_entries: usize,
    /// Strategy used for node splits on overflow.
    split_strategy: SplitStrategy,
}

impl SpatialConfig {
    /// Default configuration (max=9, min=4, `RStar` strategy).
    ///
    /// # Default Strategy Change
    ///
    /// `SpatialIndexN::new()` defaults to `RStar` (previously `Linear`).
    /// Deserialized v2 indexes preserve `Linear` for backward compatibility.
    /// Use [`with_strategy`](Self::with_strategy) to opt into `Linear` explicitly.
    pub const DEFAULT: Self = Self {
        max_entries: DEFAULT_MAX_ENTRIES,
        min_entries: DEFAULT_MIN_ENTRIES,
        split_strategy: SplitStrategy::RStar,
    };

    /// Creates a config with the given maximum node capacity and `RStar` strategy.
    ///
    /// `min_entries` is derived as `max_entries / 2`.
    ///
    /// # Errors
    ///
    /// Returns [`SpatialError::InvalidConfig`] if `max_entries < 4`.
    pub const fn new(max_entries: usize) -> Result<Self, SpatialError> {
        if max_entries < 4 {
            return Err(SpatialError::InvalidConfig);
        }
        Ok(Self {
            max_entries,
            min_entries: max_entries / 2,
            split_strategy: SplitStrategy::RStar,
        })
    }

    /// Creates a config with the given maximum node capacity and split strategy.
    ///
    /// `min_entries` is derived as `max_entries / 2`.
    ///
    /// # Errors
    ///
    /// Returns [`SpatialError::InvalidConfig`] if `max_entries < 4`.
    pub const fn with_strategy(
        max_entries: usize,
        strategy: SplitStrategy,
    ) -> Result<Self, SpatialError> {

