/// Errors from relational engine operations.
#[non_exhaustive]
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum RelationalError {
    /// Table does not exist.
    TableNotFound(String),
    /// Table already exists.
    TableAlreadyExists(String),
    /// Column does not exist in table.
    ColumnNotFound(String),
    /// Value type doesn't match column type.
    TypeMismatch {
        /// Column name.
        column: String,
        /// Expected type.
        expected: ColumnType,
    },
    /// Null value in non-nullable column.
    NullNotAllowed(String),
    /// Index already exists.
    IndexAlreadyExists {
        /// Table name.
        table: String,
        /// Column name.
        column: String,
    },
    /// Index does not exist.
    IndexNotFound {
        /// Table name.
        table: String,
        /// Column name.
        column: String,
    },
    /// Underlying storage error.
    StorageError(String),
    /// Invalid table or column name.
    InvalidName(String),
    /// Transaction not found.
    TransactionNotFound(u64),
    /// Transaction is not active (already committed or aborted).
    TransactionInactive(u64),
    /// Lock conflict with another transaction.
    LockConflict {
        /// Transaction requesting the lock.
        tx_id: u64,
        /// Transaction holding the lock.
        blocking_tx: u64,
        /// Table name.
        table: String,
        /// Row identifier.
        row_id: u64,
    },
    /// Lock acquisition timed out.
    LockTimeout {
        /// Transaction ID.
        tx_id: u64,
        /// Table name.
        table: String,
        /// Row identifiers.
        row_ids: Vec<u64>,
    },
    /// Rollback failed.
    RollbackFailed {
        /// Transaction ID.
        tx_id: u64,
        /// Failure reason.
        reason: String,
    },
    /// Result set exceeds the maximum allowed size.
    ResultTooLarge {
        /// Operation name.
        operation: String,
        /// Actual result size.
        actual: usize,
        /// Maximum allowed size.
        max: usize,
    },
    /// Index data is corrupted.
    IndexCorrupted {
        /// Description of the corruption.
        reason: String,
    },
    /// Schema metadata is corrupted or incomplete.
    SchemaCorrupted {
        /// Table name.
        table: String,
        /// Description of the corruption.
        reason: String,
    },
    /// Maximum number of tables exceeded.
    TooManyTables {
        /// Current table count.
        current: usize,
        /// Maximum allowed tables.
        max: usize,
    },
    /// Maximum number of indexes per table exceeded.
    TooManyIndexes {
        /// Table name.
        table: String,
        /// Current index count.
        current: usize,
        /// Maximum allowed indexes.
        max: usize,
    },
    /// Query timed out.
    QueryTimeout {
        /// Operation that timed out.
        operation: String,
        /// Timeout in milliseconds.
        timeout_ms: u64,
    },
    /// Primary key constraint violation.
    PrimaryKeyViolation {
        /// Table name.
        table: String,
        /// Columns in the primary key.
        columns: Vec<String>,
        /// Duplicate value.
        value: String,
    },
    /// Unique constraint violation.
    UniqueViolation {
        /// Constraint name.
        constraint_name: String,
        /// Columns in the unique constraint.
        columns: Vec<String>,
        /// Duplicate value.

        value: String,
    },
    /// Foreign key constraint violation on insert/update.
    ForeignKeyViolation {
        /// Constraint name.
        constraint_name: String,
        /// Table with the foreign key.
        table: String,
        /// Referenced table.
        referenced_table: String,
    },
    /// Foreign key restrict prevents delete/update of referenced row.
    ForeignKeyRestrict {
        /// Constraint name.
        constraint_name: String,
        /// Table containing the referenced row.
        table: String,
        /// Table with the referencing foreign key.
        referencing_table: String,
        /// Number of rows that reference this row.
        row_count: usize,
    },
    /// Constraint not found.
    ConstraintNotFound {
        /// Table name.
        table: String,
        /// Constraint name.
        constraint_name: String,
    },
    /// Constraint already exists.
    ConstraintAlreadyExists {
        /// Table name.
        table: String,
        /// Constraint name.
        constraint_name: String,
    },
    /// Column has a constraint that prevents the operation.
    ColumnHasConstraint {
        /// Column name.
        column: String,
        /// Constraint name.
        constraint_name: String,
    },
    /// Cannot add column due to constraint or data issue.
    CannotAddColumn {
        /// Column name.
        column: String,
        /// Reason the column cannot be added.
        reason: String,
    },
    /// Column already exists in the table.
    ColumnAlreadyExists {
        /// Table name.
        table: String,
        /// Column name.
        column: String,
    },
    /// Condition tree exceeds maximum nesting depth.
    ConditionTooDeep {
        /// Maximum allowed depth.
        max_depth: usize,
    },
}

impl std::fmt::Display for RelationalError {
    #[allow(clippy::too_many_lines)]
